import { Request, Response, NextFunction } from 'express'
import jwt from 'jsonwebtoken'
import { config } from '../config/index.js'
import { rbacService } from '../services/rbacService.js'

// 扩展 Express Request 类型
declare global {
    namespace Express {
        interface Request {
            user?: {
                id: string
                email: string
                role: string      // roleCode (如 "ADMIN", "SALES")
                roleId: string    // Role 表的 ID
            }
        }
    }
}

export interface JwtPayload {
    sub: string
    email: string
    role: string    // roleCode
    roleId: string  // Role 表 ID
    iat: number
    exp: number
}

// ==================== 自定义错误类 ====================

/** Token 已被撤销（黑名单中） */
class TokenRevokedError extends Error {
    constructor() {
        super('令牌已失效')
        this.name = 'TokenRevokedError'
    }
}

// ==================== 公共 Token 验证 ====================

/**
 * 统一的 Token 验证函数（单一职责）
 * 1. JWT 签名验证
 * 2. Token 黑名单检查（Redis，含降级）
 *
 * @throws jwt.TokenExpiredError - Token 已过期
 * @throws jwt.JsonWebTokenError - Token 无效
 * @throws TokenRevokedError     - Token 已被撤销
 */
async function verifyAndDecodeToken(token: string): Promise<JwtPayload> {
    // 1) 验证 JWT 签名和过期时间
    const decoded = jwt.verify(token, config.jwt.secret) as JwtPayload

    // 2) 检查 Token 是否在黑名单中（已登出）
    try {
        const { tokenBlacklist } = await import('../config/redis.js')
        const isBlacklisted = await tokenBlacklist.isBlacklisted(token)
        if (isBlacklisted) {
            throw new TokenRevokedError()
        }
    } catch (error) {
        // TokenRevokedError 需要向上传播
        if (error instanceof TokenRevokedError) throw error
        // Redis 不可用时降级，跳过黑名单检查
        console.warn('Token 黑名单检查跳过: Redis 不可用')
    }

    return decoded
}

/**
 * 从请求头提取 Bearer Token
 * @returns token 字符串，或 null（未提供）
 */
function extractBearerToken(req: Request): string | null {
    const authHeader = req.headers.authorization
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return null
    }
    return authHeader.substring(7)
}

/**
 * 将 JwtPayload 映射为 req.user 对象
 */
function payloadToUser(decoded: JwtPayload): NonNullable<Request['user']> {
    return {
        id: decoded.sub,
        email: decoded.email,
        role: decoded.role,
        roleId: decoded.roleId || '',
    }
}

/**
 * 统一的 Token 错误响应处理
 */
function handleTokenError(res: Response, error: unknown, context: string = '认证') {
    if (error instanceof TokenRevokedError) {
        return res.status(401).json({
            code: 'TOKEN_REVOKED',
            message: '令牌已失效，请重新登录',
        })
    }

    if (error instanceof jwt.TokenExpiredError) {
        return res.status(401).json({
            code: 'TOKEN_EXPIRED',
            message: `${context}令牌已过期`,
        })
    }

    return res.status(401).json({
        code: 'INVALID_TOKEN',
        message: `无效的${context}令牌`,
    })
}

// ==================== 认证中间件 ====================

/**
 * JWT 认证中间件（通用）
 * 验证 Token 有效性 + 黑名单检查，不限制角色
 */
export async function authMiddleware(req: Request, res: Response, next: NextFunction) {
    const token = extractBearerToken(req)

    if (!token) {
        return res.status(401).json({
            code: 'UNAUTHORIZED',
            message: '未提供认证令牌',
        })
    }

    try {
        const decoded = await verifyAndDecodeToken(token)
        req.user = payloadToUser(decoded)
        next()
    } catch (error) {
        return handleTokenError(res, error, '认证')
    }
}

/**
 * 可选认证中间件 (不强制要求登录)
 * Token 无效时静默忽略，不阻断请求
 */
export async function optionalAuth(req: Request, res: Response, next: NextFunction) {
    const token = extractBearerToken(req)

    if (token) {
        try {
            const decoded = await verifyAndDecodeToken(token)
            req.user = payloadToUser(decoded)
        } catch {
            // 可选认证: 忽略错误，继续处理请求
        }
    }

    next()
}

/**
 * 客户专用认证中间件
 * 验证 Token + 黑名单检查 + 仅允许 CUSTOMER 角色
 */
export async function customerAuth(req: Request, res: Response, next: NextFunction) {
    const token = extractBearerToken(req)

    if (!token) {
        return res.status(401).json({
            code: 'UNAUTHORIZED',
            message: '请登录客户门户',
        })
    }

    try {
        const decoded = await verifyAndDecodeToken(token)

        if (decoded.role !== 'CUSTOMER') {
            return res.status(403).json({
                code: 'FORBIDDEN',
                message: '此接口仅限客户访问',
            })
        }

        req.user = payloadToUser(decoded)
        next()
    } catch (error) {
        return handleTokenError(res, error, '登录')
    }
}

/**
 * 管理端认证中间件
 * 验证 Token + 黑名单检查 + 禁止 CUSTOMER 角色
 */
export async function adminAuth(req: Request, res: Response, next: NextFunction) {
    const token = extractBearerToken(req)

    if (!token) {
        return res.status(401).json({
            code: 'UNAUTHORIZED',
            message: '请登录管理系统',
        })
    }

    try {
        const decoded = await verifyAndDecodeToken(token)

        if (decoded.role === 'CUSTOMER') {
            return res.status(403).json({
                code: 'FORBIDDEN',
                message: '客户无权访问管理系统',
            })
        }

        req.user = payloadToUser(decoded)
        next()
    } catch (error) {
        return handleTokenError(res, error, '登录')
    }
}

// ==================== 授权中间件 ====================

/**
 * 角色授权中间件 (基于角色代码检查)
 * @deprecated 建议使用 requirePermission 进行细粒度控制
 */
export function requireRole(...roles: string[]) {
    return (req: Request, res: Response, next: NextFunction) => {
        if (!req.user) {
            return res.status(401).json({
                code: 'UNAUTHORIZED',
                message: '未认证',
            })
        }

        if (!roles.includes(req.user.role)) {
            return res.status(403).json({
                code: 'FORBIDDEN',
                message: '无权限访问此资源',
            })
        }

        next()
    }
}

/**
 * 权限授权中间件 (RBAC 细粒度控制)
 * @param permissionCode 权限代码，如 "leads:create", "projects:delete"
 */
export function requirePermission(permissionCode: string) {
    return async (req: Request, res: Response, next: NextFunction) => {
        if (!req.user) {
            return res.status(401).json({
                code: 'UNAUTHORIZED',
                message: '未登录',
            })
        }

        // ADMIN 超级权限兜底 (防止死锁)
        if (req.user.role === 'ADMIN') {
            return next()
        }

        try {
            const canAccess = await rbacService.hasPermission(req.user.role, permissionCode)

            if (!canAccess) {
                return res.status(403).json({
                    code: 'FORBIDDEN',
                    message: `权限不足: ${permissionCode}`,
                })
            }

            next()
        } catch (error) {
            console.error('RBAC 检查失败:', error)
            return res.status(500).json({
                code: 'INTERNAL_ERROR',
                message: '权限检查失败',
            })
        }
    }
}

import { Request, Response, NextFunction } from 'express'
import { error } from '../utils/responseHelper.js'
import logger from '../config/logger.js'

// 自定义错误类
export class AppError extends Error {
    statusCode: number
    code: string

    constructor(message: string, statusCode = 500, code = 'INTERNAL_ERROR') {
        super(message)
        this.statusCode = statusCode
        this.code = code
        Error.captureStackTrace(this, this.constructor)
    }
}

// 常用错误
export class NotFoundError extends AppError {
    constructor(message = '资源不存在') {
        super(message, 404, 'NOT_FOUND')
    }
}

export class BadRequestError extends AppError {
    constructor(message = '请求参数错误') {
        super(message, 400, 'BAD_REQUEST')
    }
}

export class UnauthorizedError extends AppError {
    constructor(message = '未授权') {
        super(message, 401, 'UNAUTHORIZED')
    }
}

export class ForbiddenError extends AppError {
    constructor(message = '禁止访问') {
        super(message, 403, 'FORBIDDEN')
    }
}

export class ConflictError extends AppError {
    constructor(message = '资源冲突') {
        super(message, 409, 'CONFLICT')
    }
}

// 业务验证错误
export class ValidationError extends AppError {
    details?: Record<string, unknown>

    constructor(message: string, details?: Record<string, unknown>) {
        super(message, 400, 'VALIDATION_ERROR')
        this.details = details
    }
}

// 业务逻辑错误
export class BusinessLogicError extends AppError {
    constructor(message: string, code = 'BUSINESS_ERROR') {
        super(message, 422, code)
    }
}

/**
 * 全局错误处理中间件
 */
export function errorHandler(
    err: Error,
    req: Request,
    res: Response,
    _next: NextFunction
) {
    logger.error('请求错误', {
        error: err.message,
        stack: err.stack,
        method: req.method,
        path: req.path,
        context: 'errorHandler',
    })

    if (err instanceof AppError) {
        return res.status(err.statusCode).json(error(err.message, err.statusCode, err.code))
    }

    // Prisma 错误处理
    if (err.name === 'PrismaClientKnownRequestError') {
        const prismaError = err as { code?: string }
        const errorCode = prismaError.code

        // P2002: Unique constraint failed
        if (errorCode === 'P2002') {
            return res.status(409).json(error('资源冲突：该记录已存在', 409, 'CONFLICT'))
        }

        // P2025: Record not found
        if (errorCode === 'P2025') {
            return res.status(404).json(error('未找到记录', 404, 'NOT_FOUND'))
        }

        return res.status(400).json(error('数据库操作失败', 400, 'DATABASE_ERROR'))
    }

    // 默认错误
    const msg = process.env.NODE_ENV === 'development' ? err.message : '服务器内部错误'
    res.status(500).json(error(msg, 500, 'INTERNAL_ERROR'))
}

import { Request, Response, NextFunction } from 'express'
import { validationResult } from 'express-validator'

/**
 * 验证中间件 - 检查 express-validator 的验证结果
 */
export function validate(req: Request, res: Response, next: NextFunction) {
    const errors = validationResult(req)

    if (!errors.isEmpty()) {
        return res.status(400).json({
            code: 'VALIDATION_ERROR',
            message: '请求参数验证失败',
            details: errors.array().map(err => ({
                field: 'path' in err ? err.path : 'unknown',
                message: err.msg,
            })),
        })
    }

    next()
}

import { prisma } from '../config/index.js'
import type { PrismaClient } from '@prisma/client'

/**
 * 基础 Repository 接口
 */
export interface IBaseRepository<T, CreateInput, UpdateInput> {
    findById(id: string): Promise<T | null>
    findAll(filters?: any): Promise<T[]>
    create(data: CreateInput): Promise<T>
    update(id: string, data: UpdateInput): Promise<T>
    delete(id: string): Promise<T>
    count(filters?: any): Promise<number>
}

/**
 * 分页选项
 */
export interface PaginationOptions {
    page: number
    limit: number
    sortBy?: string
    sortOrder?: 'asc' | 'desc'
}

/**
 * 分页结果
 */
export interface PaginatedResult<T> {
    data: T[]
    pagination: {
        page: number
        limit: number
        total: number
        totalPages: number
    }
}

/**
 * 基础 Repository 抽象类
 * 封装通用的 CRUD 操作
 */
export abstract class BaseRepository<T, CreateInput, UpdateInput> implements IBaseRepository<T, CreateInput, UpdateInput> {
    protected prisma: PrismaClient
    protected abstract modelName: string

    constructor() {
        this.prisma = prisma
    }

    /**
     * 获取 Prisma 模型代理
     */
    protected get model(): any {
        return (this.prisma as any)[this.modelName]
    }

    /**
     * 根据 ID 查找
     */
    async findById(id: string, include?: any): Promise<T | null> {
        return this.model.findUnique({
            where: { id },
            include
        })
    }

    /**
     * 查找所有记录
     */
    async findAll(filters?: any, include?: any): Promise<T[]> {
        return this.model.findMany({
            where: filters,
            include
        })
    }

    /**
     * 分页查询
     */
    async findPaginated(
        filters: any,
        pagination: PaginationOptions,
        include?: any
    ): Promise<PaginatedResult<T>> {
        const { page, limit, sortBy, sortOrder } = pagination
        const skip = (page - 1) * limit

        const orderBy = sortBy ? { [sortBy]: sortOrder || 'asc' } : undefined

        const [data, total] = await Promise.all([
            this.model.findMany({
                where: filters,
                skip,
                take: limit,
                orderBy,
                include
            }),
            this.model.count({ where: filters })
        ])

        return {
            data,
            pagination: {
                page,
                limit,
                total,
                totalPages: Math.ceil(total / limit)
            }
        }
    }

    /**
     * 创建记录
     */
    async create(data: CreateInput, include?: any): Promise<T> {
        return this.model.create({
            data,
            include
        })
    }

    /**
     * 更新记录
     */
    async update(id: string, data: UpdateInput, include?: any): Promise<T> {
        return this.model.update({
            where: { id },
            data,
            include
        })
    }

    /**
     * 删除记录
     */
    async delete(id: string): Promise<T> {
        return this.model.delete({
            where: { id }
        })
    }

    /**
     * 计数
     */
    async count(filters?: any): Promise<number> {
        return this.model.count({
            where: filters
        })
    }

    /**
     * 检查是否存在
     */
    async exists(id: string): Promise<boolean> {
        const count = await this.model.count({
            where: { id }
        })
        return count > 0
    }

    /**
     * 根据条件查找单条记录
     */
    async findFirst(filters: any, include?: any): Promise<T | null> {
        return this.model.findFirst({
            where: filters,
            include
        })
    }

    /**
     * 批量创建
     */
    async createMany(data: CreateInput[]): Promise<{ count: number }> {
        return this.model.createMany({
            data,
            skipDuplicates: true
        })
    }

    /**
     * 批量更新
     */
    async updateMany(filters: any, data: UpdateInput): Promise<{ count: number }> {
        return this.model.updateMany({
            where: filters,
            data
        })
    }

    /**
     * 批量删除
     */
    async deleteMany(filters: any): Promise<{ count: number }> {
        return this.model.deleteMany({
            where: filters
        })
    }

    /**
     * 事务操作
     */
    async transaction<R>(fn: (tx: PrismaClient) => Promise<R>): Promise<R> {
        return this.prisma.$transaction(fn as any) as Promise<R>
    }
}

