import { prisma } from '../config/index.js'
import logger from '../config/logger.js'

interface DateRange {
    startDate?: string
    endDate?: string
}

export const analyticsService = {
    /**
     * 获取销售漏斗数据
     * 统计各阶段线索数量和转化率
     */
    async getSalesFunnel(params: DateRange) {
        const where = buildDateFilter(params)

        // 各阶段线索数量
        const stages = ['NEW', 'CONTACTED', 'QUALIFIED', 'IN_PROGRESS', 'CONVERTED', 'LOST']
        const counts = await Promise.all(
            stages.map(async (stage) => {
                const count = await prisma.lead.count({
                    where: {
                        ...where,
                        status: stage as 'NEW' | 'CONTACTED' | 'QUALIFIED' | 'IN_PROGRESS' | 'CONVERTED' | 'LOST',
                        deletedAt: null,
                    },
                })
                return { stage, count }
            })
        )

        const total = counts.reduce((sum, c) => sum + c.count, 0)

        return counts.map((item) => ({
            ...item,
            percentage: total > 0 ? Math.round((item.count / total) * 100) : 0,
        }))
    },

    /**
     * 获取趋势数据
     * 按月统计线索数量
     */
    async getTrend(period: string = 'month', months: number = 6) {
        const endDate = new Date()
        const startDate = new Date()
        startDate.setMonth(startDate.getMonth() - months)

        const leads = await prisma.lead.findMany({
            where: {
                createdAt: { gte: startDate, lte: endDate },
                deletedAt: null,
            },
            select: {
                createdAt: true,
                status: true,
            },
        })

        // 按月分组
        const monthlyData = new Map<string, { total: number; converted: number }>()

        for (const lead of leads) {
            const key = period === 'quarter'
                ? `${lead.createdAt.getFullYear()}-Q${Math.floor(lead.createdAt.getMonth() / 3) + 1}`
                : `${lead.createdAt.getFullYear()}-${String(lead.createdAt.getMonth() + 1).padStart(2, '0')}`

            const current = monthlyData.get(key) || { total: 0, converted: 0 }
            current.total++
            if (lead.status === 'CONVERTED') current.converted++
            monthlyData.set(key, current)
        }

        return Array.from(monthlyData.entries())
            .sort(([a], [b]) => a.localeCompare(b))
            .map(([period, data]) => ({
                period,
                total: data.total,
                converted: data.converted,
                conversionRate: data.total > 0 ? Math.round((data.converted / data.total) * 100) : 0,
            }))
    },

    /**
     * 获取渠道效果
     */
    async getChannelMetrics(params: DateRange) {
        const where = buildDateFilter(params)

        const leads = await prisma.lead.findMany({
            where: { ...where, deletedAt: null },
            select: {
                sourceChannel: true,
                status: true,
                score: true,
            },
        })

        // 按渠道分组
        const channelData = new Map<string, { count: number; converted: number; totalScore: number }>()

        for (const lead of leads) {
            const channel = lead.sourceChannel || 'unknown'
            const current = channelData.get(channel) || { count: 0, converted: 0, totalScore: 0 }
            current.count++
            if (lead.status === 'CONVERTED') current.converted++
            current.totalScore += lead.score
            channelData.set(channel, current)
        }

        return Array.from(channelData.entries()).map(([channel, data]) => ({
            channel,
            leadCount: data.count,
            convertedCount: data.converted,
            conversionRate: data.count > 0 ? Math.round((data.converted / data.count) * 100) : 0,
            avgScore: data.count > 0 ? Math.round(data.totalScore / data.count) : 0,
        }))
    },

    /**
     * 获取团队绩效
     */
    async getTeamPerformance(params: DateRange) {
        const where = buildDateFilter(params)

        const leads = await prisma.lead.findMany({
            where: { ...where, deletedAt: null, assignedToId: { not: null } },
            select: {
                assignedToId: true,
                status: true,
                assignedTo: {
                    select: { id: true, name: true, avatarUrl: true },
                },
            },
        })

        // 按销售人员分组
        const teamData = new Map<string, {
            name: string
            avatarUrl: string | null
            total: number
            converted: number
            inProgress: number
        }>()

        for (const lead of leads) {
            if (!lead.assignedTo) continue
            const userId = lead.assignedTo.id
            const current = teamData.get(userId) || {
                name: lead.assignedTo.name,
                avatarUrl: lead.assignedTo.avatarUrl,
                total: 0,
                converted: 0,
                inProgress: 0,
            }
            current.total++
            if (lead.status === 'CONVERTED') current.converted++
            if (['CONTACTED', 'QUALIFIED', 'IN_PROGRESS'].includes(lead.status)) current.inProgress++
            teamData.set(userId, current)
        }

        return Array.from(teamData.entries())
            .map(([userId, data]) => ({
                userId,
                ...data,
                conversionRate: data.total > 0 ? Math.round((data.converted / data.total) * 100) : 0,
            }))
            .sort((a, b) => b.converted - a.converted) // 按转化数排名
    },

    /**
     * 预测分析
     * 基于历史趋势简单预测
     */
    async getForecast(months: number = 3) {
        // 获取过去 6 个月的月度数据
        const historicalData = await this.getTrend('month', 6)

        if (historicalData.length < 2) {
            return { forecast: [], message: '数据不足，无法预测' }
        }

        // 简单线性回归预测
        const totals = historicalData.map((d) => d.total)
        const avgGrowth = totals.length > 1
            ? (totals[totals.length - 1] - totals[0]) / (totals.length - 1)
            : 0
        const lastTotal = totals[totals.length - 1]
        const lastConversionRate = historicalData[historicalData.length - 1].conversionRate

        const forecast = []
        const now = new Date()

        for (let i = 1; i <= months; i++) {
            const futureDate = new Date(now)
            futureDate.setMonth(futureDate.getMonth() + i)
            const predictedTotal = Math.max(0, Math.round(lastTotal + avgGrowth * i))

            forecast.push({
                period: `${futureDate.getFullYear()}-${String(futureDate.getMonth() + 1).padStart(2, '0')}`,
                predictedLeads: predictedTotal,
                predictedConversions: Math.round(predictedTotal * lastConversionRate / 100),
                confidence: Math.max(30, 90 - i * 15), // 信心度随时间递减
            })
        }

        logger.info('生成预测数据', { months, dataPoints: historicalData.length, context: 'analytics' })

        return { forecast, basedOnMonths: historicalData.length }
    },
}

/**
 * 构建日期范围过滤条件
 */
function buildDateFilter(params: DateRange) {
    const where: Record<string, unknown> = {}
    if (params.startDate || params.endDate) {
        where.createdAt = {}
        if (params.startDate) (where.createdAt as Record<string, unknown>).gte = new Date(params.startDate)
        if (params.endDate) (where.createdAt as Record<string, unknown>).lte = new Date(params.endDate)
    }
    return where
}

import { prisma } from '../config/index.js'
import logger from '../config/logger.js'

interface AuditLogInput {
    userId: string
    action: string
    resource: string
    resourceId?: string
    ipAddress?: string
    userAgent?: string
    details?: Record<string, unknown>
}

interface AuditQueryParams {
    page?: number
    limit?: number
    userId?: string
    action?: string
    resource?: string
    startDate?: string
    endDate?: string
}

export const auditService = {
    /**
     * 记录审计事件
     */
    async logAction(input: AuditLogInput) {
        try {
            await prisma.auditLog.create({
                data: {
                    userId: input.userId,
                    action: input.action,
                    resource: input.resource,
                    resourceId: input.resourceId,
                    ipAddress: input.ipAddress,
                    userAgent: input.userAgent,
                    details: input.details ? (input.details as any) : undefined,
                },
            })
        } catch (error) {
            // 审计日志写入失败不应阻塞业务
            logger.error('审计日志写入失败', {
                error: error instanceof Error ? error.message : '未知错误',
                input,
                context: 'auditService',
            })
        }
    },

    /**
     * 查询审计日志（分页 + 筛选）
     */
    async getAuditLogs(params: AuditQueryParams) {
        const page = params.page || 1
        const limit = Math.min(params.limit || 20, 100)
        const skip = (page - 1) * limit

        const where: Record<string, unknown> = {}

        if (params.userId) where.userId = params.userId
        if (params.action) where.action = params.action
        if (params.resource) where.resource = params.resource

        if (params.startDate || params.endDate) {
            const createdAt: Record<string, Date> = {}
            if (params.startDate) createdAt.gte = new Date(params.startDate)
            if (params.endDate) createdAt.lte = new Date(params.endDate)
            where.createdAt = createdAt
        }

        const [total, data] = await Promise.all([
            prisma.auditLog.count({ where }),
            prisma.auditLog.findMany({
                where,
                include: {
                    user: {
                        select: { id: true, name: true, email: true },
                    },
                },
                orderBy: { createdAt: 'desc' },
                skip,
                take: limit,
            }),
        ])

        return {
            data,
            pagination: {
                page,
                limit,
                total,
                totalPages: Math.ceil(total / limit),
            },
        }
    },
}

import bcrypt from 'bcryptjs'
import jwt from 'jsonwebtoken'
// @ts-ignore: otplib 在某些 ESM/TS 配置下的类型定义与实际运行时导出存在差异，在此显式忽略 tsc 检查以确保项目正常编译
import otplibDefault from '@otplib/preset-default'
const { authenticator } = otplibDefault
import QRCode from 'qrcode'
import { prisma, config } from '../config/index.js'
import { UnauthorizedError, NotFoundError, BadRequestError } from '../middlewares/index.js'

interface LoginInput {
    email: string
    password: string
}

interface RegisterInput {
    email: string
    password: string
    name: string
}

export const authService = {
    /**
     * 用户登录
     */
    async login({ email, password }: LoginInput) {
        const user = await prisma.user.findUnique({
            where: { email },
            include: { role: true },
        })

        if (!user) {
            throw new UnauthorizedError('邮箱或密码错误')
        }

        if (user.status !== 'ACTIVE') {
            throw new UnauthorizedError('账户已被禁用')
        }

        const isPasswordValid = await bcrypt.compare(password, user.passwordHash)
        if (!isPasswordValid) {
            throw new UnauthorizedError('邮箱或密码错误')
        }

        // 检查是否开启了双因素认证
        if (user.twoFactorEnabled) {
            const tempToken = jwt.sign(
                { sub: user.id, type: '2fa_temp' },
                config.jwt.secret,
                { expiresIn: '5m' }
            )
            return {
                requires2FA: true,
                tempToken,
                message: '请输入双重认证验证码',
            }
        }

        const accessToken = this.generateAccessToken(user)
        const refreshToken = this.generateRefreshToken(user)

        return {
            accessToken,
            refreshToken,
            tokenType: 'Bearer',
            expiresIn: 900, // 15 分钟
            user: {
                id: user.id,
                name: user.name,
                email: user.email,
                role: user.role.code,
                roleId: user.roleId,
                avatarUrl: user.avatarUrl,
            },
        }
    },

    /**
     * 验证双因素验证码进行最终登录
     */
    async verify2FALogin(tempToken: string, code: string) {
        try {
            const decoded = jwt.verify(tempToken, config.jwt.secret) as any
            if (decoded.type !== '2fa_temp') {
                throw new UnauthorizedError('无效的会话')
            }

            const user = await prisma.user.findUnique({
                where: { id: decoded.sub },
                include: { role: true },
            })

            if (!user || user.status !== 'ACTIVE' || !user.twoFactorEnabled || !user.twoFactorSecret) {
                throw new UnauthorizedError('2FA 验证环境失效')
            }

            const isValid = authenticator.verify({ token: code, secret: user.twoFactorSecret })
            if (!isValid) {
                throw new UnauthorizedError('验证码错误')
            }

            const accessToken = this.generateAccessToken(user)
            const refreshToken = this.generateRefreshToken(user)

            return {
                accessToken,
                refreshToken,
                tokenType: 'Bearer',
                expiresIn: 900,
                user: {
                    id: user.id,
                    name: user.name,
                    email: user.email,
                    role: user.role.code,
                    roleId: user.roleId,
                    avatarUrl: user.avatarUrl,
                },
            }
        } catch (e: any) {
            if (e instanceof UnauthorizedError) throw e
            throw new UnauthorizedError('会话已失效，请重新登录')
        }
    },

    /**
     * 生成 2FA 密钥并返回绑定二维码 (设置开启用)
     */
    async generate2FA(userId: string) {
        const user = await prisma.user.findUnique({ where: { id: userId } })
        if (!user) throw new NotFoundError('用户不存在')

        const secret = authenticator.generateSecret()
        const otpauthUrl = authenticator.keyuri(user.email, 'TongHai CRM', secret)

        // 临时保存在数据库，此时尚未启用，如果中途终止也不会产生影响
        await prisma.user.update({
            where: { id: userId },
            data: { twoFactorSecret: secret, twoFactorEnabled: false }
        })

        const qrCodeUrl = await QRCode.toDataURL(otpauthUrl)

        return {
            secret,
            qrCodeUrl
        }
    },

    /**
     * 内部登录之后、用户设置的确认与激活
     */
    async verifyAndEnable2FA(userId: string, code: string) {
        const user = await prisma.user.findUnique({ where: { id: userId } })
        if (!user || !user.twoFactorSecret) throw new BadRequestError('请先获取验证二维码')

        const isValid = authenticator.verify({ token: code, secret: user.twoFactorSecret })
        if (!isValid) {
            throw new UnauthorizedError('验证码错误')
        }

        await prisma.user.update({
            where: { id: userId },
            data: { twoFactorEnabled: true }
        })

        return { success: true }
    },

    /**
     * 关闭 2FA，需要校验当前的有效码
     */
    async disable2FA(userId: string, code: string) {
        const user = await prisma.user.findUnique({ where: { id: userId } })
        if (!user || !user.twoFactorEnabled || !user.twoFactorSecret) {
            throw new BadRequestError('当前未启用 2FA')
        }

        const isValid = authenticator.verify({ token: code, secret: user.twoFactorSecret })
        if (!isValid) {
            throw new UnauthorizedError('验证码错误')
        }

        await prisma.user.update({
            where: { id: userId },
            data: { twoFactorEnabled: false, twoFactorSecret: null }
        })

        return { success: true }
    },

    /**
     * 用户注册
     */
    async register({ email, password, name }: RegisterInput) {
        const existingUser = await prisma.user.findUnique({
            where: { email },
        })

        if (existingUser) {
            // 使用通用错误消息，防止用户枚举攻击
            throw new UnauthorizedError('注册失败，请检查输入信息')
        }

        // 获取 CUSTOMER 角色
        const customerRole = await prisma.role.findUnique({ where: { code: 'CUSTOMER' } })
        if (!customerRole) {
            throw new Error('系统配置错误: CUSTOMER 角色不存在')
        }

        const passwordHash = await bcrypt.hash(password, 12)

        const user = await prisma.user.create({
            data: {
                email,
                name,
                passwordHash,
                roleId: customerRole.id,
            },
            include: { role: true },
        })

        return {
            id: user.id,
            name: user.name,
            email: user.email,
            role: user.role.code,
        }
    },

    /**
     * 刷新 Token
     */
    async refreshToken(refreshToken: string) {
        try {
            const { tokenBlacklist } = await import('../config/redis.js')
            const isBlacklisted = await tokenBlacklist.isBlacklisted(refreshToken)
            if (isBlacklisted) {
                throw new UnauthorizedError('凭证已失效（黑名单拦截），请重新登录')
            }

            // 使用独立的 refreshSecret 验证刷新令牌
            const decoded = jwt.verify(refreshToken, config.jwt.refreshSecret) as any

            if (decoded.type !== 'refresh') {
                throw new UnauthorizedError('无效的刷新令牌')
            }

            const user = await prisma.user.findUnique({
                where: { id: decoded.sub },
                include: { role: true },
            })

            if (!user || user.status !== 'ACTIVE') {
                throw new UnauthorizedError('用户不存在或已被禁用')
            }

            const accessToken = this.generateAccessToken(user)

            return {
                accessToken,
                expiresIn: 900,
            }
        } catch (error) {
            throw new UnauthorizedError('刷新令牌无效或已过期')
        }
    },

    /**
     * 获取当前用户信息
     */
    async getCurrentUser(userId: string) {
        const user = await prisma.user.findUnique({
            where: { id: userId },
            select: {
                id: true,
                email: true,
                name: true,
                roleId: true,
                role: { select: { code: true, name: true } },
                department: true,
                avatarUrl: true,
                status: true,
                twoFactorEnabled: true,
                createdAt: true,
            },
        })

        if (!user) {
            throw new NotFoundError('用户不存在')
        }

        return {
            ...user,
            roleCode: user.role.code,
            roleName: user.role.name,
        }
    },

    /**
     * 生成访问令牌
     */
    generateAccessToken(user: { id: string; email: string; role: { code: string }; roleId: string }) {
        return jwt.sign(
            {
                sub: user.id,
                email: user.email,
                role: user.role.code,
                roleId: user.roleId,
                type: 'access',
            },
            config.jwt.secret,
            { expiresIn: config.jwt.expiresIn as `${number}${'s' | 'm' | 'h' | 'd'}` }
        )
    },

    /**
     * 生成刷新令牌
     */
    generateRefreshToken(user: { id: string }) {
        return jwt.sign(
            {
                sub: user.id,
                type: 'refresh',
            },
            // 使用独立的 refreshSecret（更高安全性）
            config.jwt.refreshSecret,
            { expiresIn: config.jwt.refreshExpiresIn as `${number}${'s' | 'm' | 'h' | 'd'}` }
        )
    },

    /**
     * 验证设置密码 Token
     */
    async validateSetupToken(token: string) {
        const user = await prisma.user.findFirst({
            where: {
                setupToken: token,
                setupTokenExpiry: { gt: new Date() },
            },
        })

        if (!user) {
            throw new UnauthorizedError('链接无效或已过期')
        }

        return {
            valid: true,
            email: user.email,
            name: user.name,
        }
    },

    /**
     * 首次登录设置密码
     */
    async setupPassword(token: string, password: string) {
        const user = await prisma.user.findFirst({
            where: {
                setupToken: token,
                setupTokenExpiry: { gt: new Date() },
            },
        })

        if (!user) {
            throw new UnauthorizedError('链接无效或已过期')
        }

        const passwordHash = await bcrypt.hash(password, 12)

        const updatedUser = await prisma.user.update({
            where: { id: user.id },
            data: {
                passwordHash,
                setupToken: null,
                setupTokenExpiry: null,
            },
            include: { role: true },
        })

        // 自动登录
        const accessToken = this.generateAccessToken(updatedUser)
        const refreshToken = this.generateRefreshToken(updatedUser)

        return {
            success: true,
            message: '密码设置成功',
            accessToken,
            refreshToken,
            tokenType: 'Bearer',
            expiresIn: 900,
            user: {
                id: updatedUser.id,
                name: updatedUser.name,
                email: updatedUser.email,
                role: updatedUser.role,
                avatarUrl: updatedUser.avatarUrl,
            },
        }
    },
}

