import { prisma } from '../config/index.js'

export const documentService = {
    /**
     * 获取当前用户的文档
     */
    async getMyDocuments(userId: string, projectId?: string) {
        // 查找用户关联的 Customer
        const user = await prisma.user.findUnique({ where: { id: userId } })
        if (!user) return []

        return prisma.document.findMany({
            where: {
                projectId: projectId || undefined,
                project: {
                    customer: {
                        lead: {
                            email: user.email
                        }
                    }
                },
                accessLevel: { in: ['PUBLIC', 'TEAM'] } // 门户可见级别
            },
            include: {
                project: { select: { title: true } },
                uploadedBy: { select: { name: true } }
            },
            orderBy: { createdAt: 'desc' }
        })
    },

    /**
     * 上传文档
     */
    async uploadDocument(data: {
        projectId: string
        fileName: string
        filePath: string
        fileType: string
        fileSize: number
        uploadedById: string
        accessLevel?: 'PRIVATE' | 'TEAM' | 'PUBLIC'
    }) {
        // 验证项目是否存在且用户有权限
        // 对于客户，只能上传到自己的项目
        // 简化起见，这里假设 Controller 层或 Middleware 已经做了基本校验，
        // 或者在这里查一下 Project 的 customerId/ownerId。
        // 但 MVP 阶段先直接写入。

        return prisma.document.create({
            data: {
                projectId: data.projectId,
                fileName: data.fileName,
                filePath: data.filePath,
                fileType: data.fileType,
                fileSize: data.fileSize,
                uploadedById: data.uploadedById,
                accessLevel: (data.accessLevel as any) || 'private', // default
                documentType: 'UPLOAD'
            }
        })
    },

    /**
     * 获取文档详情（用于下载）
     */
    async getDocumentById(id: string) {
        return prisma.document.findUnique({
            where: { id }
        })
    }
}

import { prisma } from '../config/index.js'
import nodemailer from 'nodemailer'

interface EmailOptions {
    to: string | string[]
    subject: string
    html: string
    text?: string
    from?: string
    replyTo?: string
    attachments?: Array<{
        filename: string
        content: Buffer | string
        contentType?: string
    }>
}

interface EmailResult {
    success: boolean
    messageId?: string
    error?: string
}

type EmailProvider = 'SMTP' | 'SENDGRID' | 'AWS_SES' | 'CONSOLE'

interface EmailConfig {
    provider: EmailProvider
    smtp?: {
        host: string
        port: number
        secure: boolean
        auth: {
            user: string
            pass: string
        }
    }
    sendgrid?: {
        apiKey: string
    }
    awsSes?: {
        region: string
        accessKeyId: string
        secretAccessKey: string
    }
    defaultFrom: string
}

// 默认配置（开发环境使用控制台输出）
const emailConfig: EmailConfig = {
    provider: 'CONSOLE',
    defaultFrom: 'noreply@tonghai.sg'
}

export const emailSenderService = {
    /**
     * 初始化邮件配置
     */
    async initialize(): Promise<void> {
        try {
            // 从系统设置加载配置
            const [provider, smtpHost, smtpPort, smtpUser, smtpPass, defaultFrom] = await Promise.all([
                prisma.systemSetting.findUnique({ where: { key: 'EMAIL_PROVIDER' } }),
                prisma.systemSetting.findUnique({ where: { key: 'SMTP_HOST' } }),
                prisma.systemSetting.findUnique({ where: { key: 'SMTP_PORT' } }),
                prisma.systemSetting.findUnique({ where: { key: 'SMTP_USER' } }),
                prisma.systemSetting.findUnique({ where: { key: 'SMTP_PASS' } }),
                prisma.systemSetting.findUnique({ where: { key: 'EMAIL_FROM' } }),
            ])

            if (provider?.value) {
                emailConfig.provider = provider.value as EmailProvider
            }

            if (defaultFrom?.value) {
                emailConfig.defaultFrom = defaultFrom.value
            }

            if (smtpHost?.value && smtpUser?.value && smtpPass?.value) {
                emailConfig.smtp = {
                    host: smtpHost.value,
                    port: parseInt(smtpPort?.value || '587'),
                    secure: (smtpPort?.value || '587') === '465',
                    auth: {
                        user: smtpUser.value,
                        pass: smtpPass.value
                    }
                }
            }

            console.log(`📧 邮件服务已初始化，提供商: ${emailConfig.provider}`)
        } catch (error) {
            console.warn('⚠️ 邮件配置加载失败，使用控制台模式')
        }
    },

    /**
     * 发送邮件
     */
    async send(options: EmailOptions): Promise<EmailResult> {
        const from = options.from || emailConfig.defaultFrom

        switch (emailConfig.provider) {
            case 'SMTP':
                return this.sendViaSMTP({ ...options, from })

            case 'SENDGRID':
                return this.sendViaSendGrid({ ...options, from })

            case 'AWS_SES':
                return this.sendViaAwsSes({ ...options, from })

            case 'CONSOLE':
            default:
                return this.sendViaConsole({ ...options, from })
        }
    },

    /**
     * 通过 SMTP 发送
     */
    async sendViaSMTP(options: EmailOptions & { from: string }): Promise<EmailResult> {
        if (!emailConfig.smtp) {
            return { success: false, error: 'SMTP 配置缺失' }
        }

        try {
            const transporter = nodemailer.createTransport({
                host: emailConfig.smtp.host,
                port: emailConfig.smtp.port,
                secure: emailConfig.smtp.secure,
                auth: emailConfig.smtp.auth
            })

            const result = await transporter.sendMail({
                from: options.from,
                to: Array.isArray(options.to) ? options.to.join(', ') : options.to,
                subject: options.subject,
                html: options.html,
                text: options.text,
                replyTo: options.replyTo,
                attachments: options.attachments
            })

            return {
                success: true,
                messageId: result.messageId
            }
        } catch (error: any) {
            console.error('SMTP 发送失败:', error)
            return {
                success: false,
                error: error.message
            }
        }
    },

    /**
     * 通过 SendGrid 发送
     */
    async sendViaSendGrid(options: EmailOptions & { from: string }): Promise<EmailResult> {
        if (!emailConfig.sendgrid?.apiKey) {
            return { success: false, error: 'SendGrid API Key 缺失' }
        }

        try {
            // 动态导入 SendGrid（可选依赖）
            // @ts-ignore - 可选依赖，运行时才加载
            const sgMail = await import('@sendgrid/mail')
            sgMail.default.setApiKey(emailConfig.sendgrid.apiKey)

            const msg = {
                to: options.to,
                from: options.from,
                subject: options.subject,
                html: options.html,
                text: options.text || options.html.replace(/<[^>]*>/g, '')
            }

            const [response] = await (sgMail.default as any).send(msg)

            return {
                success: true,
                messageId: (response as any).headers?.['x-message-id'] || `sg-${Date.now()}`
            }
        } catch (error: any) {
            console.error('SendGrid 发送失败:', error)
            return {
                success: false,
                error: error.message
            }
        }
    },

    /**
     * 通过 AWS SES 发送
     */
    async sendViaAwsSes(options: EmailOptions & { from: string }): Promise<EmailResult> {
        if (!emailConfig.awsSes) {
            return { success: false, error: 'AWS SES 配置缺失' }
        }

        try {
            // 动态导入 AWS SDK（可选依赖）
            // @ts-ignore - 可选依赖，运行时才加载
            const { SESClient, SendEmailCommand } = await import('@aws-sdk/client-ses')

            const client = new SESClient({
                region: emailConfig.awsSes.region,
                credentials: {
                    accessKeyId: emailConfig.awsSes.accessKeyId,
                    secretAccessKey: emailConfig.awsSes.secretAccessKey
                }
            })

            const toAddresses = Array.isArray(options.to) ? options.to : [options.to]

            const command = new SendEmailCommand({
                Source: options.from,
                Destination: {
                    ToAddresses: toAddresses
                },
                Message: {
                    Subject: { Data: options.subject },
                    Body: {
                        Html: { Data: options.html },
                        Text: { Data: options.text || options.html.replace(/<[^>]*>/g, '') }
                    }
                }
            })

            const response = await client.send(command)

            return {
                success: true,
                messageId: response.MessageId
            }
        } catch (error: any) {
            console.error('AWS SES 发送失败:', error)
            return {
                success: false,
                error: error.message
            }
        }
    },

    /**
     * 控制台输出（开发模式）
     */
    async sendViaConsole(options: EmailOptions & { from: string }): Promise<EmailResult> {
        console.log('\n' + '='.repeat(60))
        console.log('📧 [开发模式] 邮件发送模拟')
        console.log('='.repeat(60))
        console.log(`From:    ${options.from}`)
        console.log(`To:      ${Array.isArray(options.to) ? options.to.join(', ') : options.to}`)
        console.log(`Subject: ${options.subject}`)
        console.log('-'.repeat(60))
        console.log('Body (HTML):')
        console.log(options.html.substring(0, 500) + (options.html.length > 500 ? '...' : ''))
        console.log('='.repeat(60) + '\n')

        return {
            success: true,
            messageId: `console-${Date.now()}`
        }
    },

    /**
     * 测试邮件连接
     */
    async testConnection(): Promise<{ success: boolean; message: string }> {
        try {
            if (emailConfig.provider === 'CONSOLE') {
                return { success: true, message: '控制台模式，无需测试连接' }
            }

            if (emailConfig.provider === 'SMTP' && emailConfig.smtp) {
                const transporter = nodemailer.createTransport({
                    host: emailConfig.smtp.host,
                    port: emailConfig.smtp.port,
                    secure: emailConfig.smtp.secure,
                    auth: emailConfig.smtp.auth
                })

                await transporter.verify()
                return { success: true, message: 'SMTP 连接成功' }
            }

            return { success: true, message: `${emailConfig.provider} 配置已加载` }
        } catch (error: any) {
            return { success: false, message: error.message }
        }
    },

    /**
     * 获取当前配置状态
     */
    getStatus(): { provider: EmailProvider; configured: boolean } {
        return {
            provider: emailConfig.provider,
            configured: emailConfig.provider === 'CONSOLE' ||
                (emailConfig.provider === 'SMTP' && !!emailConfig.smtp) ||
                (emailConfig.provider === 'SENDGRID' && !!emailConfig.sendgrid?.apiKey) ||
                (emailConfig.provider === 'AWS_SES' && !!emailConfig.awsSes)
        }
    }
}

export default emailSenderService

import { prisma } from '../config/index.js'
import type { Lead, Customer } from '@prisma/client'

interface CreateTemplateInput {
    name: string
    subject: string
    body: string
    category?: string
    description?: string
    variables?: string[]
}

interface UpdateTemplateInput {
    name?: string
    subject?: string
    body?: string
    category?: string
    description?: string
    variables?: string[]
    isActive?: boolean
}

interface SendEmailInput {
    templateId?: string
    recipient: string
    subject: string
    body: string
    leadId?: string
    customerId?: string
}

interface TemplateContext {
    lead?: Partial<Lead>
    customer?: Partial<Customer>
    custom?: Record<string, string>
}

export const emailTemplateService = {
    // ==================== 模板管理 ====================

    /**
     * 获取所有模板
     */
    async getTemplates(category?: string, includeInactive = false) {
        const where: any = {}

        if (category) {
            where.category = category
        }
        if (!includeInactive) {
            where.isActive = true
        }

        return prisma.emailTemplate.findMany({
            where,
            orderBy: { name: 'asc' },
            include: {
                createdBy: {
                    select: { id: true, name: true }
                }
            }
        })
    },

    /**
     * 获取模板详情
     */
    async getTemplateById(id: string) {
        return prisma.emailTemplate.findUnique({
            where: { id },
            include: {
                createdBy: {
                    select: { id: true, name: true }
                }
            }
        })
    },

    /**
     * 创建模板
     */
    async createTemplate(data: CreateTemplateInput, creatorId?: string) {
        // 自动提取变量列表
        const extractedVars = this.extractVariables(data.subject + ' ' + data.body)
        const variables = data.variables || extractedVars

        return prisma.emailTemplate.create({
            data: {
                name: data.name,
                subject: data.subject,
                body: data.body,
                category: data.category || 'GENERAL',
                description: data.description,
                variables,
                createdById: creatorId
            }
        })
    },

    /**
     * 更新模板
     */
    async updateTemplate(id: string, data: UpdateTemplateInput) {
        const updateData: any = { ...data }

        // 如果更新了内容，自动提取变量
        if (data.subject || data.body) {
            const template = await this.getTemplateById(id)
            if (template) {
                const content = (data.subject || template.subject) + ' ' + (data.body || template.body)
                updateData.variables = this.extractVariables(content)
            }
        }

        return prisma.emailTemplate.update({
            where: { id },
            data: updateData
        })
    },

    /**
     * 删除模板
     */
    async deleteTemplate(id: string) {
        return prisma.emailTemplate.delete({
            where: { id }
        })
    },

    // ==================== 变量处理 ====================

    /**
     * 从内容中提取变量
     */
    extractVariables(content: string): string[] {
        const regex = /\{\{(\w+)\}\}/g
        const matches = content.matchAll(regex)
        const vars = new Set<string>()

        for (const match of matches) {
            vars.add(`{{${match[1]}}}`)
        }

        return Array.from(vars)
    },

    /**
     * 替换变量
     */
    replaceVariables(content: string, context: TemplateContext): string {
        let result = content

        // 替换 Lead 相关变量
        if (context.lead) {
            const lead = context.lead
            result = result.replace(/\{\{lead\.(\w+)\}\}/g, (match, key) => {
                const value = lead[key as keyof typeof lead]
                return value != null ? String(value) : match
            })
            // 简化变量名
            result = result.replace(/\{\{name\}\}/g, lead.contactName || '{{name}}')
            result = result.replace(/\{\{company\}\}/g, lead.companyName || '{{company}}')
            result = result.replace(/\{\{email\}\}/g, lead.email || '{{email}}')
            result = result.replace(/\{\{phone\}\}/g, lead.phone || '{{phone}}')
        }

        // 替换 Customer 相关变量
        if (context.customer) {
            const customer = context.customer
            result = result.replace(/\{\{customer\.(\w+)\}\}/g, (match, key) => {
                const value = customer[key as keyof typeof customer]
                return value != null ? String(value) : match
            })
            result = result.replace(/\{\{name\}\}/g, customer.contactName || '{{name}}')
            result = result.replace(/\{\{company\}\}/g, customer.companyName || '{{company}}')
        }

        // 替换自定义变量
        if (context.custom) {
            for (const [key, value] of Object.entries(context.custom)) {
                result = result.replace(new RegExp(`\\{\\{${key}\\}\\}`, 'g'), value)
            }
        }

        return result
    },

    /**
     * 预览模板（替换变量后的结果）
     */
    async previewTemplate(templateId: string, context: TemplateContext) {
        const template = await this.getTemplateById(templateId)
        if (!template) {
            throw new Error('模板不存在')
        }

        return {
            subject: this.replaceVariables(template.subject, context),
            body: this.replaceVariables(template.body, context),
            originalTemplate: template
        }
    },

    // ==================== 邮件发送 ====================

    /**
     * 使用模板生成邮件内容
     */
    async generateEmail(templateId: string, recipient: string, context: TemplateContext) {
        const preview = await this.previewTemplate(templateId, context)

        return {
            recipient,
            subject: preview.subject,
            body: preview.body,
            templateId
        }
    },

    /**
     * 发送邮件（记录日志）
     */
    async sendEmail(input: SendEmailInput, senderId?: string): Promise<any> {
        // 动态导入邮件发送服务避免循环依赖
        const { emailSenderService } = await import('./emailSenderService.js')

        // 创建发送记录
        const log = await prisma.emailLog.create({
            data: {
                templateId: input.templateId,
                recipient: input.recipient,
                subject: input.subject,
                body: input.body,
                leadId: input.leadId,
                customerId: input.customerId,
                sentById: senderId,
                status: 'PENDING'
            }
        })

        // 调用实际邮件发送服务
        try {
            const result = await emailSenderService.send({
                to: input.recipient,
                subject: input.subject,
                html: input.body
            })

            if (result.success) {
                await prisma.emailLog.update({
                    where: { id: log.id },
                    data: {
                        status: 'SENT',
                        sentAt: new Date()
                    }
                })
                return { success: true, logId: log.id, messageId: result.messageId }
            } else {
                await prisma.emailLog.update({
                    where: { id: log.id },
                    data: {
                        status: 'FAILED',
                        errorMsg: result.error
                    }
                })
                return { success: false, logId: log.id, error: result.error }
            }
        } catch (error: any) {
            await prisma.emailLog.update({
                where: { id: log.id },
                data: {
                    status: 'FAILED',
                    errorMsg: error.message
                }
            })

            return { success: false, logId: log.id, error: error.message }
        }
    },

    /**
     * 使用模板发送邮件
     */
    async sendWithTemplate(
        templateId: string,
        recipient: string,
        context: TemplateContext,
        options?: { leadId?: string; customerId?: string },
        senderId?: string
    ) {
        const email = await this.generateEmail(templateId, recipient, context)

        return this.sendEmail({
            ...email,
            leadId: options?.leadId,
            customerId: options?.customerId
        }, senderId)
    },

    // ==================== 发送记录查询 ====================

    /**
     * 获取发送记录列表
     */
    async getEmailLogs(filters: {
        leadId?: string;
        customerId?: string;
        templateId?: string;
        status?: string;
    }, pagination: { page: number; limit: number }) {
        const { page, limit } = pagination
        const skip = (page - 1) * limit

        const where: any = {}
        if (filters.leadId) where.leadId = filters.leadId
        if (filters.customerId) where.customerId = filters.customerId
        if (filters.templateId) where.templateId = filters.templateId
        if (filters.status) where.status = filters.status

        const [logs, total] = await Promise.all([
            prisma.emailLog.findMany({
                where,
                skip,
                take: limit,
                orderBy: { createdAt: 'desc' },
                include: {
                    template: { select: { id: true, name: true } },
                    sentBy: { select: { id: true, name: true } }
                }
            }),
            prisma.emailLog.count({ where })
        ])

        return {
            data: logs,
            pagination: {
                page,
                limit,
                total,
                totalPages: Math.ceil(total / limit)
            }
        }
    },

    // ==================== 预置模板种子数据 ====================

    /**
