import { prisma } from '../config/index.js'
import logger from '../config/logger.js'

interface CreateFaqCategoryInput {
    name: string
    nameEn?: string
    description?: string
    sortOrder?: number
}

interface UpdateFaqCategoryInput {
    name?: string
    nameEn?: string
    description?: string
    sortOrder?: number
    isActive?: boolean
}

interface CreateFaqItemInput {
    question: string
    questionEn?: string
    answer: string
    answerEn?: string
    keywords?: string[]
    categoryId: string
    sortOrder?: number
}

interface UpdateFaqItemInput {
    question?: string
    questionEn?: string
    answer?: string
    answerEn?: string
    keywords?: string[]
    categoryId?: string
    sortOrder?: number
    isActive?: boolean
}

export const faqService = {
    // ==================== 分类管理 ====================

    /**
     * 获取所有分类
     */
    async getCategories(includeInactive = false) {
        const where = includeInactive ? {} : { isActive: true }

        return prisma.faqCategory.findMany({
            where,
            include: {
                _count: {
                    select: { items: true }
                }
            },
            orderBy: { sortOrder: 'asc' }
        })
    },

    /**
     * 获取分类详情
     */
    async getCategoryById(id: string) {
        return prisma.faqCategory.findUnique({
            where: { id },
            include: {
                items: {
                    where: { isActive: true },
                    orderBy: { sortOrder: 'asc' }
                }
            }
        })
    },

    /**
     * 创建分类
     */
    async createCategory(data: CreateFaqCategoryInput) {
        return prisma.faqCategory.create({
            data: {
                name: data.name,
                nameEn: data.nameEn,
                description: data.description,
                sortOrder: data.sortOrder ?? 0
            }
        })
    },

    /**
     * 更新分类
     */
    async updateCategory(id: string, data: UpdateFaqCategoryInput) {
        return prisma.faqCategory.update({
            where: { id },
            data
        })
    },

    /**
     * 删除分类
     */
    async deleteCategory(id: string) {
        // 软删除
        return prisma.faqCategory.update({
            where: { id },
            data: { isActive: false }
        })
    },

    // ==================== FAQ 条目管理 ====================

    /**
     * 获取所有 FAQ 条目
     */
    async getItems(categoryId?: string, includeInactive = false) {
        const where: any = {}

        if (!includeInactive) {
            where.isActive = true
        }

        if (categoryId) {
            where.categoryId = categoryId
        }

        const items = await prisma.faqItem.findMany({
            where,
            include: {
                category: {
                    select: { id: true, name: true, nameEn: true }
                }
            },
            orderBy: [
                { category: { sortOrder: 'asc' } },
                { sortOrder: 'asc' }
            ]
        })
        logger.debug(`getItems 查询到 ${items.length} 条 FAQ`, { filter: where, context: 'faqService' })
        return items
    },

    /**
     * 获取 FAQ 详情
     */
    async getItemById(id: string) {
        return prisma.faqItem.findUnique({
            where: { id },
            include: {
                category: true
            }
        })
    },

    /**
     * 创建 FAQ 条目
     */
    async createItem(data: CreateFaqItemInput) {
        return prisma.faqItem.create({
            data: {
                question: data.question,
                questionEn: data.questionEn,
                answer: data.answer,
                answerEn: data.answerEn,
                keywords: data.keywords ?? [],
                categoryId: data.categoryId,
                sortOrder: data.sortOrder ?? 0
            },
            include: {
                category: true
            }
        })
    },

    /**
     * 更新 FAQ 条目
     */
    async updateItem(id: string, data: UpdateFaqItemInput) {
        return prisma.faqItem.update({
            where: { id },
            data,
            include: {
                category: true
            }
        })
    },

    /**
     * 删除 FAQ 条目
     */
    async deleteItem(id: string) {
        return prisma.faqItem.update({
            where: { id },
            data: { isActive: false }
        })
    },

    /**
     * 增加查看次数
     */
    async incrementViewCount(id: string) {
        return prisma.faqItem.update({
            where: { id },
            data: { viewCount: { increment: 1 } }
        })
    },

    /**
     * 增加有帮助次数
     */
    async incrementHelpfulCount(id: string) {
        return prisma.faqItem.update({
            where: { id },
            data: { helpfulCount: { increment: 1 } }
        })
    },

    // ==================== 搜索功能 ====================

    /**
     * 搜索 FAQ（关键词匹配）
     */

    /**
     * searchFaqs - 优化版本，支持中文分词
     */
    async searchFaqs(query: string, locale: 'zh' | 'en' = 'zh') {
        // 对中文进行字符级分词，对英文进行空格分词
        const normalizedQuery = query.toLowerCase().trim()

        // 中文分词：将连续中文字符拆分为 2-3 字的词组
        const chineseChars = normalizedQuery.match(/[\u4e00-\u9fa5]+/g) || []
        const chineseTerms: string[] = []
        for (const chars of chineseChars) {
            // 添加完整词
            chineseTerms.push(chars)
            // 添加 2 字词组
            for (let i = 0; i < chars.length - 1; i++) {
                chineseTerms.push(chars.substring(i, i + 2))
            }
        }

        // 英文分词：按空格分割
        const englishTerms = normalizedQuery.split(/\s+/).filter(t => t.length > 1 && !/[\u4e00-\u9fa5]/.test(t))

        const searchTerms = [...new Set([...chineseTerms, ...englishTerms])]

        logger.debug(`FAQ 搜索: "${query}"`, { searchTerms, context: 'faqSearch' })

        const items = await prisma.faqItem.findMany({
            where: { isActive: true },
            include: {
                category: {
                    select: { id: true, name: true, nameEn: true }
                }
            }
        })

        logger.debug(`FAQ 搜索数据库匹配`, { totalItems: items.length, context: 'faqSearch' })

        // 计算匹配分数
        const scored = items.map(item => {
            let score = 0
            const question = locale === 'en' && item.questionEn ? item.questionEn.toLowerCase() : item.question.toLowerCase()
            const answer = (locale === 'en' && item.answerEn ? item.answerEn : item.answer) || ''
            const answerLower = answer.toLowerCase()
            const keywords = item.keywords.map(k => k.toLowerCase())

            for (const term of searchTerms) {
                // 问题匹配
                if (question.includes(term)) score += 10
                // 答案匹配（权重较低）
                if (answerLower.includes(term)) score += 3
                // 关键词精确匹配
                if (keywords.includes(term)) score += 20
                // 关键词模糊匹配
                if (keywords.some(k => k.includes(term) || term.includes(k))) score += 5
            }

            return { ...item, score }
        })

        const results = scored
            .filter(item => item.score > 0)
            .sort((a, b) => b.score - a.score)
            .slice(0, 5) // 返回前5个最匹配的结果

        logger.debug(`FAQ 搜索结果`, { count: results.length, topScore: results[0]?.score || 0, context: 'faqSearch' })

        return results
    },

    // ==================== 批量导入 ====================

    /**
     * 从 Excel/CSV Buffer 导入数据（使用 ExcelJS）
     */
    async importFromBuffer(buffer: Buffer) {
        const ExcelJS = await import('exceljs')
        const workbook = new ExcelJS.Workbook()
        await workbook.xlsx.load(buffer as unknown as ArrayBuffer)

        // 读取第一个 sheet
        const worksheet = workbook.worksheets[0]
        if (!worksheet) {
            throw new Error('Excel 文件中没有工作表')
        }

        // 读取表头（第一行）
        const headers: string[] = []
        const headerRow = worksheet.getRow(1)
        headerRow.eachCell((cell, colNumber) => {
            headers[colNumber] = String(cell.value || '').trim()
        })

        const results = {
            success: 0,
            failed: 0,
            errors: [] as string[]
        }

        // 缓存分类 ID map: name -> id
        const categoryMap = new Map<string, string>()

        // 获取现有分类
        const existingCats = await prisma.faqCategory.findMany()
        existingCats.forEach(cat => categoryMap.set(cat.name, cat.id))

        // 遍历数据行（从第2行开始，跳过表头）
        for (let rowIndex = 2; rowIndex <= worksheet.rowCount; rowIndex++) {
            const excelRow = worksheet.getRow(rowIndex)
            const lineNum = rowIndex // Excel 行号

            // 构建 key-value 行数据
            const row: Record<string, string> = {}
            excelRow.eachCell((cell, colNumber) => {
                const header = headers[colNumber]
                if (header) {
                    row[header] = String(cell.value || '').trim()
                }
            })

            // 跳过空行
            if (Object.values(row).every(v => !v)) continue

            try {
                // 必填字段检查
                if (!row['Category'] && !row['分类']) throw new Error('缺少分类')
                if (!row['Question'] && !row['问题']) throw new Error('缺少问题')
                if (!row['Answer'] && !row['答案']) throw new Error('缺少答案')

                const catName = (row['Category'] || row['分类']).trim()
                const question = (row['Question'] || row['问题']).trim()
                const answer = (row['Answer'] || row['答案']).trim()
                const questionEn = (row['QuestionEn'] || row['英文问题'] || '').trim()
                const answerEn = (row['AnswerEn'] || row['英文答案'] || '').trim()
                const keywordsData = row['Keywords'] || row['关键词'] || ''

                // 处理 keywords (支持逗号、中文逗号、空格分隔)
                const keywords = String(keywordsData)
                    .split(/[,\uFF0C\s]+/)
                    .map(k => k.trim())
                    .filter(k => k.length > 0)

                // 获取或创建分类
                let catId = categoryMap.get(catName)
                if (!catId) {
                    const newCat = await prisma.faqCategory.create({
                        data: { name: catName }
                    })
                    catId = newCat.id
                    categoryMap.set(catName, catId)
                }

                // 创建 FAQ
                await prisma.faqItem.create({
                    data: {
                        question,
                        questionEn: questionEn || null,
                        answer,
                        answerEn: answerEn || null,
                        keywords,
                        categoryId: catId,
                        sortOrder: 100 // 默认排序
                    }
                })

                results.success++
            } catch (error: unknown) {
                results.failed++
                const msg = error instanceof Error ? error.message : '未知错误'
                results.errors.push(`第 ${lineNum} 行: ${msg}`)
            }
        }

        return results
    }
}

import { prisma } from '../config/index.js'
import { Decimal } from '@prisma/client/runtime/library'

interface InvoiceItem {
    description: string
    quantity: number
    unitPrice: number
    amount: number
}

interface CreateInvoiceInput {
    projectId: string
    customerId: string
    title: string
    items: InvoiceItem[]
    taxRate?: number
    currency?: string
    issueDate: string
    dueDate: string
    notes?: string
    terms?: string
}

interface UpdateInvoiceInput {
    title?: string
    items?: InvoiceItem[]
    taxRate?: number
    issueDate?: string
    dueDate?: string
    notes?: string
    terms?: string
    status?: string
}

interface CreatePaymentInput {
    invoiceId: string
    amount: number
    currency?: string
    exchangeRate?: number
    paymentMethod: string
    paymentDate: string
    reference?: string
    notes?: string
    attachmentUrl?: string
}

export const invoiceService = {
    // ==================== 发票管理 ====================

    /**
     * 生成发票号
     */
    async generateInvoiceNumber(): Promise<string> {
        const year = new Date().getFullYear()
        const month = String(new Date().getMonth() + 1).padStart(2, '0')

        // 获取当月发票数量
        const count = await prisma.invoice.count({
            where: {
                invoiceNumber: {
                    startsWith: `INV-${year}${month}`
                }
            }
        })

        const sequence = String(count + 1).padStart(4, '0')
        return `INV-${year}${month}-${sequence}`
    },

    /**
     * 获取发票列表
     */
    async getInvoices(filters: {
        projectId?: string
        customerId?: string
        status?: string
    }, pagination: { page: number; limit: number }) {
        const { page, limit } = pagination
        const skip = (page - 1) * limit

        const where: any = {}
        if (filters.projectId) where.projectId = filters.projectId
        if (filters.customerId) where.customerId = filters.customerId
        if (filters.status) where.status = filters.status

        const [invoices, total] = await Promise.all([
            prisma.invoice.findMany({
                where,
                skip,
                take: limit,
                orderBy: { createdAt: 'desc' },
                include: {
                    project: { select: { id: true, title: true } },
                    createdBy: { select: { id: true, name: true } },
                    _count: { select: { payments: true } }
                }
            }),
            prisma.invoice.count({ where })
        ])

        return {
            data: invoices,
            pagination: {
                page,
                limit,
                total,
                totalPages: Math.ceil(total / limit)
            }
        }
    },

    /**
     * 获取发票详情
     */
    async getInvoiceById(id: string) {
        return prisma.invoice.findUnique({
            where: { id },
            include: {
                project: { select: { id: true, title: true, customer: true } },
                createdBy: { select: { id: true, name: true } },
                payments: {
                    orderBy: { paymentDate: 'desc' },
                    include: {
                        recordedBy: { select: { id: true, name: true } }
                    }
                }
            }
        })
    },

    /**
     * 创建发票
     */
    async createInvoice(data: CreateInvoiceInput, creatorId?: string) {
        const invoiceNumber = await this.generateInvoiceNumber()

        // 计算金额
        const subtotal = data.items.reduce((sum, item) => sum + item.amount, 0)
        const taxRate = data.taxRate || 0
        const taxAmount = subtotal * taxRate
        const totalAmount = subtotal + taxAmount

        return prisma.invoice.create({
            data: {
                invoiceNumber,
                projectId: data.projectId,
                customerId: data.customerId,
                title: data.title,
                items: data.items as any,
                subtotal: new Decimal(subtotal),
                taxRate: new Decimal(taxRate),
                taxAmount: new Decimal(taxAmount),
                totalAmount: new Decimal(totalAmount),
                currency: data.currency || 'SGD',
                issueDate: new Date(data.issueDate),
                dueDate: new Date(data.dueDate),
                notes: data.notes,
                terms: data.terms,
                createdById: creatorId
            },
            include: {
                project: { select: { id: true, title: true } }
            }
        })
    },

    /**
     * 更新发票
     */
    async updateInvoice(id: string, data: UpdateInvoiceInput) {
        const updateData: any = { ...data }

        // 如果更新了明细项，重新计算金额
        if (data.items) {
            const subtotal = data.items.reduce((sum, item) => sum + item.amount, 0)
            const invoice = await this.getInvoiceById(id)
            const taxRate = data.taxRate ?? (invoice as any)?.taxRate ?? 0
            const taxAmount = subtotal * Number(taxRate)
            const totalAmount = subtotal + taxAmount

            updateData.subtotal = new Decimal(subtotal)
            updateData.taxAmount = new Decimal(taxAmount)
            updateData.totalAmount = new Decimal(totalAmount)
        }

        if (data.issueDate) updateData.issueDate = new Date(data.issueDate)
        if (data.dueDate) updateData.dueDate = new Date(data.dueDate)
        if (data.taxRate !== undefined) updateData.taxRate = new Decimal(data.taxRate)

        return prisma.invoice.update({
            where: { id },
            data: updateData
        })
    },

    /**
     * 删除发票
     */
    async deleteInvoice(id: string) {
        // 检查是否有收款记录
        const payments = await prisma.payment.count({ where: { invoiceId: id } })
        if (payments > 0) {
            throw new Error('无法删除已有收款记录的发票')
        }

        return prisma.invoice.delete({ where: { id } })
    },

    /**
     * 发送发票
     */
    async sendInvoice(id: string) {
        return prisma.invoice.update({
            where: { id },
            data: { status: 'SENT' }
        })
    },

    /**
     * 取消发票
     */
    async cancelInvoice(id: string) {
        return prisma.invoice.update({
            where: { id },
            data: { status: 'CANCELLED' }
        })
    },

    // ==================== 收款管理 ====================

    /**
     * 记录收款
     */
    async recordPayment(data: CreatePaymentInput, recorderId?: string) {
        const invoice = await this.getInvoiceById(data.invoiceId)
        if (!invoice) {
            throw new Error('发票不存在')
        }

        if (invoice.status === 'CANCELLED') {
            throw new Error('无法为已取消的发票记录收款')
        }

        if (invoice.status === 'PAID') {
            throw new Error('发票已全额付款')
        }

        // 计算发票货币金额
        const exchangeRate = data.exchangeRate || 1
        const amountInInvoiceCurrency = data.amount * exchangeRate

        // 创建收款记录
        const payment = await prisma.payment.create({
            data: {
                invoiceId: data.invoiceId,
                amount: new Decimal(data.amount),
                currency: data.currency || invoice.currency,
                exchangeRate: new Decimal(exchangeRate),
                amountInInvoiceCurrency: new Decimal(amountInInvoiceCurrency),
                paymentMethod: data.paymentMethod,
                paymentDate: new Date(data.paymentDate),
                reference: data.reference,
                notes: data.notes,
                attachmentUrl: data.attachmentUrl,
                recordedById: recorderId
            }
        })

        // 更新发票已付金额和状态
        const newPaidAmount = Number(invoice.paidAmount) + amountInInvoiceCurrency
        const totalAmount = Number(invoice.totalAmount)

        let newStatus = invoice.status
        if (newPaidAmount >= totalAmount) {
            newStatus = 'PAID'
        } else if (newPaidAmount > 0) {
            newStatus = 'PARTIAL'
        }

        await prisma.invoice.update({
            where: { id: data.invoiceId },
            data: {
                paidAmount: new Decimal(newPaidAmount),
                status: newStatus
            }
        })

        return payment
    },

    /**
     * 获取收款记录列表
     */
    async getPayments(filters: { invoiceId?: string }, pagination: { page: number; limit: number }) {
        const { page, limit } = pagination
        const skip = (page - 1) * limit

        const where: any = {}
        if (filters.invoiceId) where.invoiceId = filters.invoiceId

        const [payments, total] = await Promise.all([
            prisma.payment.findMany({
                where,
                skip,
                take: limit,
                orderBy: { paymentDate: 'desc' },
                include: {
                    invoice: { select: { id: true, invoiceNumber: true, totalAmount: true, currency: true } },
                    recordedBy: { select: { id: true, name: true } }
                }
            }),
            prisma.payment.count({ where })
        ])

        return {
            data: payments,
            pagination: {
                page,
                limit,
                total,
                totalPages: Math.ceil(total / limit)
            }
        }
    },

    /**
     * 删除收款记录
     */
    async deletePayment(id: string) {
        const payment = await prisma.payment.findUnique({
            where: { id },
            include: { invoice: true }
        })

        if (!payment) {
            throw new Error('收款记录不存在')
        }

        // 更新发票已付金额
        const newPaidAmount = Number(payment.invoice.paidAmount) - Number(payment.amountInInvoiceCurrency)

        let newStatus = payment.invoice.status
        if (newPaidAmount <= 0) {
            newStatus = 'SENT'
        } else if (newPaidAmount < Number(payment.invoice.totalAmount)) {
            newStatus = 'PARTIAL'
        }

        await prisma.$transaction([
            prisma.payment.delete({ where: { id } }),
            prisma.invoice.update({
                where: { id: payment.invoiceId },
                data: {
                    paidAmount: new Decimal(Math.max(0, newPaidAmount)),
                    status: newStatus
                }
            })
        ])

        return { success: true }
    },

    // ==================== 统计 ====================

    /**
     * 获取发票统计
     */
    async getInvoiceStats(customerId?: string) {
        const where: any = customerId ? { customerId } : {}

        const [
            totalInvoices,
            byStatus,
            totalAmount,
            paidAmount
        ] = await Promise.all([
            prisma.invoice.count({ where }),
            prisma.invoice.groupBy({
                by: ['status'],
                where,
                _count: true,
                _sum: { totalAmount: true }
            }),
            prisma.invoice.aggregate({
                where,
                _sum: { totalAmount: true }
            }),
            prisma.invoice.aggregate({
                where,
                _sum: { paidAmount: true }
            })
        ])

        const outstanding = Number(totalAmount._sum.totalAmount || 0) - Number(paidAmount._sum.paidAmount || 0)

        return {
            totalInvoices,
            totalAmount: Number(totalAmount._sum.totalAmount || 0),
            paidAmount: Number(paidAmount._sum.paidAmount || 0),
            outstandingAmount: outstanding,
            byStatus: byStatus.reduce((acc, item) => {
                acc[item.status] = {
                    count: item._count,
                    amount: Number(item._sum.totalAmount || 0)
                }
                return acc
            }, {} as Record<string, { count: number; amount: number }>)
        }
    },

    /**
     * 检查逾期发票
     */
    async checkOverdueInvoices() {
        const now = new Date()

        // 查找逾期但未标记的发票
        const overdueInvoices = await prisma.invoice.findMany({
            where: {
                status: { in: ['SENT', 'PARTIAL'] },
                dueDate: { lt: now }
            }
        })

        // 更新状态为逾期
        if (overdueInvoices.length > 0) {
            await prisma.invoice.updateMany({
                where: {
                    id: { in: overdueInvoices.map(i => i.id) }
                },
                data: { status: 'OVERDUE' }
            })
        }

        return { updated: overdueInvoices.length }
    }
}

