/**
 * 新闻服务 - 文章管理
 */
import { prisma } from '../config/index.js'

export interface CreateArticleInput {
    title: string
    titleEn?: string
    content: string
    contentEn?: string
    summary?: string
    summaryEn?: string
    coverImage?: string
    source: string
    sourceUrl?: string
    sourceId?: string
    author?: string
    type?: string
    category?: string
    tags?: string[]
    status?: string
    isTop?: boolean
    rssFeedId?: string
    publishedAt?: Date
}

export interface UpdateArticleInput extends Partial<CreateArticleInput> { }

export interface ArticleFilters {
    type?: string
    category?: string
    status?: string
    source?: string
    search?: string
}

export const newsService = {
    /**
     * 获取已发布的文章列表（公开接口）
     */
    async getPublishedArticles(options: {
        type?: string
        category?: string
        page?: number
        pageSize?: number
        locale?: string
    }) {
        const { type, category, page = 1, pageSize = 10, locale = 'zh' } = options

        const where: any = {
            status: 'PUBLISHED',
        }

        if (type) {
            where.type = type
        }

        if (category) {
            where.category = category
        }

        const [articles, total] = await Promise.all([
            prisma.newsArticle.findMany({
                where,
                orderBy: [{ isTop: 'desc' }, { publishedAt: 'desc' }],
                skip: (page - 1) * pageSize,
                take: pageSize,
                select: {
                    id: true,
                    title: true,
                    titleEn: true,
                    summary: true,
                    summaryEn: true,
                    coverImage: true,
                    type: true,
                    category: true,
                    tags: true,
                    author: true,
                    isTop: true,
                    viewCount: true,
                    publishedAt: true,
                },
            }),
            prisma.newsArticle.count({ where }),
        ])

        // 根据语言选择字段
        const localizedArticles = articles.map((article) => ({
            id: article.id,
            title: locale === 'en' && article.titleEn ? article.titleEn : article.title,
            summary: locale === 'en' && article.summaryEn ? article.summaryEn : article.summary,
            coverImage: article.coverImage,
            type: article.type,
            category: article.category,
            tags: article.tags,
            author: article.author,
            isTop: article.isTop,
            viewCount: article.viewCount,
            publishedAt: article.publishedAt,
        }))

        return {
            articles: localizedArticles,
            pagination: {
                page,
                pageSize,
                total,
                totalPages: Math.ceil(total / pageSize),
            },
        }
    },

    /**
     * 获取文章详情（公开接口）
     */
    async getArticleById(id: string, locale: string = 'zh') {
        const article = await prisma.newsArticle.findUnique({
            where: { id },
        })

        if (!article || article.status !== 'PUBLISHED') {
            return null
        }

        // 增加浏览量
        await prisma.newsArticle.update({
            where: { id },
            data: { viewCount: { increment: 1 } },
        })

        // 根据语言返回内容
        return {
            id: article.id,
            title: locale === 'en' && article.titleEn ? article.titleEn : article.title,
            content: locale === 'en' && article.contentEn ? article.contentEn : article.content,
            summary: locale === 'en' && article.summaryEn ? article.summaryEn : article.summary,
            coverImage: article.coverImage,
            type: article.type,
            category: article.category,
            tags: article.tags,
            author: article.author,
            sourceUrl: article.sourceUrl,
            viewCount: article.viewCount + 1,
            publishedAt: article.publishedAt,
            createdAt: article.createdAt,
        }
    },

    /**
     * 获取热门文章
     */
    async getPopularArticles(limit: number = 5, locale: string = 'zh') {
        const articles = await prisma.newsArticle.findMany({
            where: { status: 'PUBLISHED' },
            orderBy: { viewCount: 'desc' },
            take: limit,
            select: {
                id: true,
                title: true,
                titleEn: true,
                coverImage: true,
                viewCount: true,
                publishedAt: true,
            },
        })

        return articles.map((article) => ({
            id: article.id,
            title: locale === 'en' && article.titleEn ? article.titleEn : article.title,
            coverImage: article.coverImage,
            viewCount: article.viewCount,
            publishedAt: article.publishedAt,
        }))
    },

    /**
     * 管理端：获取所有文章（包含草稿）
     */
    async getAllArticles(options: {
        filters?: ArticleFilters
        page?: number
        pageSize?: number
    }) {
        const { filters = {}, page = 1, pageSize = 20 } = options

        const where: any = {}

        if (filters.type) {
            where.type = filters.type
        }

        if (filters.category) {
            where.category = filters.category
        }

        if (filters.status) {
            where.status = filters.status
        }

        if (filters.source) {
            where.source = filters.source
        }

        if (filters.search) {
            where.OR = [
                { title: { contains: filters.search, mode: 'insensitive' } },
                { summary: { contains: filters.search, mode: 'insensitive' } },
            ]
        }

        const [articles, total] = await Promise.all([
            prisma.newsArticle.findMany({
                where,
                include: {
                    rssFeed: {
                        select: { id: true, name: true },
                    },
                },
                orderBy: [{ isTop: 'desc' }, { updatedAt: 'desc' }],
                skip: (page - 1) * pageSize,
                take: pageSize,
            }),
            prisma.newsArticle.count({ where }),
        ])

        return {
            articles,
            pagination: {
                page,
                pageSize,
                total,
                totalPages: Math.ceil(total / pageSize),
            },
        }
    },

    /**
     * 管理端：获取单篇文章详情
     */
    async getArticleByIdAdmin(id: string) {
        return prisma.newsArticle.findUnique({
            where: { id },
            include: {
                rssFeed: {
                    select: { id: true, name: true },
                },
            },
        })
    },

    /**
     * 创建文章
     */
    async createArticle(data: CreateArticleInput) {
        return prisma.newsArticle.create({
            data: {
                title: data.title,
                titleEn: data.titleEn,
                content: data.content,
                contentEn: data.contentEn,
                summary: data.summary,
                summaryEn: data.summaryEn,
                coverImage: data.coverImage,
                source: data.source,
                sourceUrl: data.sourceUrl,
                sourceId: data.sourceId,
                author: data.author,
                type: data.type || 'COMPANY',
                category: data.category,
                tags: data.tags || [],
                status: data.status || 'DRAFT',
                isTop: data.isTop || false,
                rssFeedId: data.rssFeedId,
                publishedAt: data.publishedAt,
            },
        })
    },

    /**
     * 更新文章
     */
    async updateArticle(id: string, data: UpdateArticleInput) {
        return prisma.newsArticle.update({
            where: { id },
            data,
        })
    },

    /**
     * 发布文章
     */
    async publishArticle(id: string) {
        return prisma.newsArticle.update({
            where: { id },
            data: {
                status: 'PUBLISHED',
                publishedAt: new Date(),
            },
        })
    },

    /**
     * 取消发布（设为草稿）
     */
    async unpublishArticle(id: string) {
        return prisma.newsArticle.update({
            where: { id },
            data: {
                status: 'DRAFT',
            },
        })
    },

    /**
     * 删除文章
     */
    async deleteArticle(id: string) {
        return prisma.newsArticle.delete({
            where: { id },
        })
    },

    /**
     * 批量删除
     */
    async deleteArticles(ids: string[]) {
        return prisma.newsArticle.deleteMany({
            where: { id: { in: ids } },
        })
    },

    /**
     * 设置/取消置顶
     */
    async toggleTop(id: string) {
        const article = await prisma.newsArticle.findUnique({
            where: { id },
            select: { isTop: true },
        })

        if (!article) {
            throw new Error('文章不存在')
        }

        return prisma.newsArticle.update({
            where: { id },
            data: { isTop: !article.isTop },
        })
    },

    /**
     * 检查文章是否已存在（用于去重）
     */
    async articleExists(source: string, sourceId: string): Promise<boolean> {
        const count = await prisma.newsArticle.count({
            where: { source, sourceId },
        })
        return count > 0
    },
}

import { prisma } from '../config/index.js'
import bcrypt from 'bcryptjs'
import { NotFoundError, UnauthorizedError } from '../middlewares/index.js'

interface UpdateProfileInput {
    name?: string
    phone?: string
    company?: string
    address?: string
}

interface ChangePasswordInput {
    currentPassword: string
    newPassword: string
}

export const portalService = {
    /**
     * 获取客户个人资料
     */
    async getProfile(userId: string) {
        const user = await prisma.user.findUnique({
            where: { id: userId },
            select: {
                id: true,
                name: true,
                email: true,
                avatarUrl: true,
                createdAt: true,
            },
        })

        if (!user) {
            throw new NotFoundError('用户不存在')
        }

        // 获取关联的客户信息
        const customer = await prisma.customer.findFirst({
            where: { userId },
            select: {
                id: true,
                companyName: true,
                phone: true,
                contactName: true,
                familyMembers: true,
                riskGrade: true,
            },
        })

        return {
            ...user,
            phone: customer?.phone || null,
            company: customer?.companyName || null,
            customerId: customer?.id || null,
            familyMembers: customer?.familyMembers || [],
            riskGrade: customer?.riskGrade || 'LOW',
        }
    },

    /**
     * 更新客户个人资料
     */
    async updateProfile(userId: string, data: UpdateProfileInput) {
        // 更新用户基本信息
        const user = await prisma.user.update({
            where: { id: userId },
            data: {
                name: data.name,
            },
            select: {
                id: true,
                name: true,
                email: true,
                avatarUrl: true,
            },
        })

        // 更新客户扩展信息
        const customer = await prisma.customer.findFirst({
            where: { userId },
        })

        if (customer) {
            await prisma.customer.update({
                where: { id: customer.id },
                data: {
                    phone: data.phone,
                    companyName: data.company,
                },
            })
        }

        return {
            success: true,
            message: '资料更新成功',
            user,
        }
    },

    /**
     * 修改密码
     */
    async changePassword(userId: string, data: ChangePasswordInput) {
        const user = await prisma.user.findUnique({
            where: { id: userId },
        })

        if (!user) {
            throw new NotFoundError('用户不存在')
        }

        // 验证当前密码
        const isValid = await bcrypt.compare(data.currentPassword, user.passwordHash)
        if (!isValid) {
            throw new UnauthorizedError('当前密码错误')
        }

        // 更新密码
        const newPasswordHash = await bcrypt.hash(data.newPassword, 12)
        await prisma.user.update({
            where: { id: userId },
            data: { passwordHash: newPasswordHash },
        })

        return {
            success: true,
            message: '密码修改成功',
        }
    },

    /**
     * 获取客户的项目列表
     */
    async getMyProjects(userId: string) {
        const customer = await prisma.customer.findFirst({
            where: { userId },
            include: {
                projects: {
                    orderBy: { createdAt: 'desc' },
                    include: {
                        documents: {
                            take: 5,
                            orderBy: { createdAt: 'desc' },
                        },
                    },
                },
            },
        })

        if (!customer) {
            return []
        }

        return customer.projects
    },

    /**
     * 获取客户的项目详情
     */
    async getProjectDetail(userId: string, projectId: string) {
        const project = await prisma.project.findFirst({
            where: {
                id: projectId,
                customer: { userId }
            },
            include: {
                customer: {
                    include: {
                        lead: {
                            include: {
                                assignedTo: {
                                    select: { id: true, name: true, email: true, avatarUrl: true }
                                }
                            }
                        }
                    }
                },
                tasks: {
                    orderBy: { dueDate: 'asc' },
                    select: {
                        id: true,
                        title: true,
                        status: true,
                        priority: true,
                        dueDate: true,
                        description: true
                    }
                },
                documents: {
                    where: {
                        accessLevel: { in: ['PUBLIC', 'TEAM'] }
                    },
                    orderBy: { createdAt: 'desc' },
                    include: {
                        uploadedBy: { select: { name: true } }
                    }
                }
            }
        })

        if (!project) {
            throw new NotFoundError('项目不存在或无权访问')
        }

        // 扁平化顾问信息
        const consultant = project.customer?.lead?.assignedTo || null

        // 移除敏感关联信息并返回
        const { customer: _customer, ...rest } = project
        return {
            ...rest,
            consultant
        }
    },

    /**
     * 获取客户的待办事项/通知
     */
    async getNotifications(userId: string) {
        const customer = await prisma.customer.findFirst({
            where: { userId },
        })

        if (!customer) {
            return []
        }

        // 获取需要客户操作的任务（如待签署文档等）
        const pendingDocuments = await prisma.document.findMany({
            where: {
                project: { customerId: customer.id },
                accessLevel: 'TEAM', // 需要客户查看的
            },
            take: 10,
            orderBy: { createdAt: 'desc' },
            select: {
                id: true,
                fileName: true,
                createdAt: true,
                project: {
                    select: { title: true },
                },
            },
        })

        // 转换为通知格式
        return pendingDocuments.map((doc) => ({
            id: doc.id,
            type: 'document',
            title: '新文档待查看',
            description: `${(doc.project?.title || 'Unknown')} - ${doc.fileName}`,
            createdAt: doc.createdAt,
        }))
    },

    /**
     * 获取仪表板统计数据
     */
    async getDashboardStats(userId: string) {
        const customer = await prisma.customer.findFirst({
            where: { userId },
            include: {
                projects: true,
            },
        })

        if (!customer) {
            return {
                totalProjects: 0,
                activeProjects: 0,
                completedProjects: 0,
                pendingDocuments: 0,
            }
        }

        const activeProjects = customer.projects.filter(
            (p) => p.status === 'ACTIVE' || p.status === 'PLANNING'
        ).length
        const completedProjects = customer.projects.filter(
            (p) => p.status === 'COMPLETED'
        ).length

        const pendingDocuments = await prisma.document.count({
            where: {
                project: { customerId: customer.id },
                accessLevel: 'TEAM',
            },
        })

        return {
            totalProjects: customer.projects.length,
            activeProjects,
            completedProjects,
            pendingDocuments,
        }
    },

    // ==================== 服务咨询 ====================

    /**
     * 创建服务咨询
     */
    async createInquiry(userId: string, data: {
        serviceType: string
        name?: string
        phone?: string
        email?: string
        message: string
        preferredContact?: string
    }) {
        const _customer = await prisma.customer.findFirst({
            where: { userId },
        })

        // 创建 Lead 作为咨询记录
        const lead = await prisma.lead.create({
            data: {
                contactName: data.name || 'Customer Inquiry',
                email: data.email || '',
                phone: data.phone || '',
                sourceChannel: 'PORTAL',
                status: 'NEW',
                inquiryMessage: `[服务类型] ${data.serviceType}\n[偏好联系方式] ${data.preferredContact || 'phone'}\n\n${data.message}`,
            },
        })

        return {
            success: true,
            message: '咨询已提交',
            inquiryId: lead.id,
        }
    },

    // ==================== 家庭成员管理 ====================

    /**
     * 添加家庭成员
     */
    async addFamilyMember(userId: string, data: {
        name: string
        relationship: string
        isBeneficiary?: boolean
    }) {
        const customer = await prisma.customer.findFirst({
            where: { userId },
        })

        if (!customer) {
            throw new NotFoundError('客户信息不存在')
        }

        // 获取现有家庭成员（JSON 字段）
        const existingMembers = (customer.familyMembers as any[]) || []

        const newMember = {
            id: `fm_${Date.now()}`,
            name: data.name,
            relationship: data.relationship,
            isBeneficiary: data.isBeneficiary || false,
            createdAt: new Date().toISOString(),
        }

        await prisma.customer.update({
            where: { id: customer.id },
            data: {
                familyMembers: [...existingMembers, newMember],
            },
        })

        return {
            success: true,
            message: '成员已添加',
            member: newMember,
        }
    },

    /**
     * 更新家庭成员
     */
    async updateFamilyMember(userId: string, memberId: string, data: {
        name?: string
        relationship?: string
        isBeneficiary?: boolean
    }) {
        const customer = await prisma.customer.findFirst({
            where: { userId },
        })

        if (!customer) {
            throw new NotFoundError('客户信息不存在')
        }

        const members = (customer.familyMembers as any[]) || []
        const memberIndex = members.findIndex(m => m.id === memberId)

        if (memberIndex === -1) {
            throw new NotFoundError('成员不存在')
        }

        members[memberIndex] = {
            ...members[memberIndex],
            ...data,
            updatedAt: new Date().toISOString(),
        }

        await prisma.customer.update({
            where: { id: customer.id },
            data: { familyMembers: members },
        })

        return {
            success: true,
            message: '成员已更新',
            member: members[memberIndex],
        }
    },

    /**
     * 删除家庭成员
     */
    async deleteFamilyMember(userId: string, memberId: string) {
        const customer = await prisma.customer.findFirst({
            where: { userId },
        })

        if (!customer) {
            throw new NotFoundError('客户信息不存在')
        }

        const members = (customer.familyMembers as any[]) || []
        const filteredMembers = members.filter(m => m.id !== memberId)

        if (filteredMembers.length === members.length) {
            throw new NotFoundError('成员不存在')
        }

        await prisma.customer.update({
            where: { id: customer.id },
            data: { familyMembers: filteredMembers },
        })

        return {
            success: true,
            message: '成员已删除',
        }
    },

    // ==================== 通知偏好 ====================

    /**
     * 更新通知偏好
     */
    async updatePreferences(userId: string, preferences: {
        email?: boolean
        sms?: boolean
        projectUpdate?: boolean
        documentReminder?: boolean
    }) {
        const customer = await prisma.customer.findFirst({
            where: { userId },
        })

        if (!customer) {
            throw new NotFoundError('客户信息不存在')
        }

        // 保存到 Customer 的 metadata 字段（如果存在）或创建专门字段
        // 这里使用一个简单方案：将偏好存储为 JSON
        await prisma.customer.update({
            where: { id: customer.id },
            data: {
                // 假设 Customer 模型有 preferences 字段或使用其他方式存储
                // 如果模型没有该字段，这里会报错，需要在 schema 中添加
                // 暂时使用 notes 字段存储（不推荐，仅演示）
            },
        })

        return {
            success: true,
            message: '偏好已保存',
            preferences,
        }
    },
}

export default portalService

import { prisma } from '../config/index.js'
import { Prisma } from '@prisma/client'

export const projectService = {
    // 获取项目列表（支持分页、筛选）
    async getProjects(params: {
        page?: number
        limit?: number
        status?: string
        customerId?: string
    }) {
        const page = params.page || 1
        const limit = params.limit || 10
        const skip = (page - 1) * limit

        const where: Prisma.ProjectWhereInput = {}
        if (params.status) where.status = params.status as any
        if (params.customerId) where.customerId = params.customerId

        const [total, projects] = await Promise.all([
            prisma.project.count({ where }),
            prisma.project.findMany({
                where,
                skip,
                take: limit,
                include: {
                    customer: {
                        include: {
                            lead: {
                                select: { contactName: true, companyName: true }
                            }
                        }
                    },
                    tasks: {
                        select: { id: true, status: true } // 用于计算简易进度
                    },
                    _count: {
                        select: { tasks: true, documents: true }
                    }
                },
                orderBy: { updatedAt: 'desc' }
            })
        ])

        return {
            data: projects,
            pagination: {
                total,
                page,
                limit,
                totalPages: Math.ceil(total / limit)
            }
        }
    },

    async getMyProjects(customerEmail: string) {
        return prisma.project.findMany({
            where: {
                customer: {
                    lead: {
                        email: customerEmail
                    }
                }
            },
            include: {
                tasks: {
                    select: { id: true, status: true }
                },
                _count: {
                    select: { tasks: true, documents: true }
                }
            },
            orderBy: { updatedAt: 'desc' }
        })
    },

    // 客户获取自己的项目详情
    async getMyProjectById(id: string, customerEmail: string) {
        return prisma.project.findFirst({
            where: {
                id,
                customer: {
                    lead: {
                        email: customerEmail
                    }
                }
            },
            include: {
                tasks: {
                    include: {
                        assignedTo: { select: { id: true, name: true, avatarUrl: true } }
                    },
                    orderBy: { dueDate: 'asc' }
                },
                documents: {
                    where: {
                        accessLevel: { in: ['PUBLIC', 'TEAM'] } // 门户能查看的文档级别（暂定）
                    },
                    orderBy: { createdAt: 'desc' },
                    include: {
                        uploadedBy: { select: { name: true } }
                    }
                }
            }
        })
    },

    // 获取单个项目详情
    async getProjectById(id: string) {
        return prisma.project.findUnique({
            where: { id },
            include: {
                customer: {
                    include: {
                        lead: true
                    }
                },
                tasks: {
                    include: {
                        assignedTo: { select: { id: true, name: true, avatarUrl: true } }
                    },
                    orderBy: { dueDate: 'asc' }
                },
                documents: {
                    orderBy: { createdAt: 'desc' },
                    include: {
                        uploadedBy: { select: { name: true } }
                    }
                }
            }
        })
    },

    // 创建项目
    async createProject(data: {
        title: string
        description?: string
        customerId: string
        projectType: string
        startDate?: string
        estimatedEndDate?: string
        budget?: number
        currency?: string
    }) {
        return prisma.project.create({
            data: {
                title: data.title,
                description: data.description,
                customerId: data.customerId,
                projectType: data.projectType,
                startDate: data.startDate ? new Date(data.startDate) : undefined,
                estimatedEndDate: data.estimatedEndDate ? new Date(data.estimatedEndDate) : undefined,
                budget: data.budget,
                currency: data.currency || 'SGD',
                status: 'PLANNING'
            }
        })
    },

    // 更新项目
    async updateProject(id: string, data: Prisma.ProjectUpdateInput) {
        return prisma.project.update({
            where: { id },
            data
        })
    },

    // 更新项目状态（看板拖拽用）
    async updateStatus(id: string, status: string) {
        return prisma.project.update({
            where: { id },
            data: { status: status as any }
        })
    },

    // 删除项目
    async deleteProject(id: string) {
        return prisma.project.delete({
            where: { id }
        })
    }
}

import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

/**
 * RBAC 服务
 * 负责权限检查、角色管理、权限管理
 */
class RBACService {
    /** 缓存 TTL: 5 分钟（毫秒） */
    private static readonly CACHE_TTL_MS = 5 * 60 * 1000

    /** 内存缓存: roleCode -> { permissions, loadedAt } */
    private cache = new Map<string, { permissions: Set<string>; loadedAt: number }>()

    /**
     * 检查角色是否拥有某权限
     */
    async hasPermission(roleCode: string, permissionCode: string): Promise<boolean> {
        // ADMIN 超级权限兜底 (防止死锁)
        if (roleCode === 'ADMIN') return true

        // 从缓存读取，过期则重新加载
        const cached = this.cache.get(roleCode)
        const isExpired = cached && (Date.now() - cached.loadedAt > RBACService.CACHE_TTL_MS)
        if (!cached || isExpired) {
            await this.loadRolePermissions(roleCode)
        }

        return this.cache.get(roleCode)?.permissions.has(permissionCode) ?? false
    }

    /**
     * 加载角色权限到缓存
     */
    private async loadRolePermissions(roleCode: string): Promise<void> {
        const role = await prisma.role.findUnique({
            where: { code: roleCode },
            include: {
                permissions: {
                    include: { permission: true }
                }
            }
        })

        if (!role) {
            this.cache.set(roleCode, { permissions: new Set(), loadedAt: Date.now() })
            return
        }

        const permissionCodes = new Set<string>(
            role.permissions.map(rp => rp.permission.code)
        )
        this.cache.set(roleCode, { permissions: permissionCodes, loadedAt: Date.now() })
    }

    /**
     * 清除角色缓存 (权限更新后调用)
     */
    clearCache(roleCode?: string): void {
        if (roleCode) {
            this.cache.delete(roleCode)
        } else {
            this.cache.clear()
        }
    }

    /**
     * 获取所有角色
     */
    async getAllRoles() {
        return prisma.role.findMany({
            orderBy: { createdAt: 'asc' },
            include: {
                _count: { select: { users: true, permissions: true } }
            }
        })
    }

    /**
     * 创建新角色
     */
    async createRole(data: { code: string; name: string; description?: string }) {
        return prisma.role.create({
            data: {
                code: data.code.toUpperCase(),
                name: data.name,
                description: data.description,
                isSystem: false
            }
        })
    }

    /**
     * 删除角色 (系统角色不可删除)
     */
    async deleteRole(roleCode: string): Promise<boolean> {
        const role = await prisma.role.findUnique({ where: { code: roleCode } })
        if (!role || role.isSystem) return false

        await prisma.role.delete({ where: { code: roleCode } })
        this.clearCache(roleCode)
        return true
    }

    /**
     * 获取所有权限
     */
    async getAllPermissions() {
        return prisma.permission.findMany({
            orderBy: [{ resource: 'asc' }, { action: 'asc' }]
        })
    }

    /**
     * 按资源分组获取权限
     */
    async getPermissionsGroupedByResource() {
        const permissions = await this.getAllPermissions()
        const grouped: Record<string, typeof permissions> = {}

        for (const p of permissions) {
            if (!grouped[p.resource]) {
                grouped[p.resource] = []
            }
            grouped[p.resource].push(p)
        }

        return grouped
    }

    /**
     * 获取角色的权限列表
     */
    async getRolePermissions(roleCode: string): Promise<string[]> {
        const role = await prisma.role.findUnique({
            where: { code: roleCode },
            include: {
                permissions: {
                    include: { permission: true }
                }
            }
        })

        if (!role) return []
        return role.permissions.map(rp => rp.permission.code)
    }

    /**
     * 更新角色权限 (接收 permissionCodes 数组)
     */
    async setRolePermissions(roleCode: string, permissionCodes: string[]): Promise<void> {
        const role = await prisma.role.findUnique({ where: { code: roleCode } })
        if (!role) throw new Error(`角色 ${roleCode} 不存在`)

        // 查找对应的 Permission IDs
        const permissions = await prisma.permission.findMany({
            where: { code: { in: permissionCodes } }
        })

        // 删除现有关联
        await prisma.rolePermission.deleteMany({
            where: { roleId: role.id }
        })

        // 创建新关联
        if (permissions.length > 0) {
            await prisma.rolePermission.createMany({
                data: permissions.map(p => ({
                    roleId: role.id,
                    permissionId: p.id
                }))
            })
        }

        // 清除缓存
        this.clearCache(roleCode)
    }

    /**
     * 获取用户的所有权限 (用于前端)
     */
    async getUserPermissions(userId: string): Promise<string[]> {
        const user = await prisma.user.findUnique({
            where: { id: userId },
            include: {
                role: {
                    include: {
                        permissions: {
                            include: { permission: true }
                        }
                    }
                }
            }
        })

        if (!user) return []

        // ADMIN 返回特殊标记
        if (user.role.code === 'ADMIN') {
            return ['*'] // 表示拥有所有权限
        }

        return user.role.permissions.map(rp => rp.permission.code)
    }
}

export const rbacService = new RBACService()

/**
 * RSS 抓取服务
 */
import { prisma } from '../config/index.js'
import { newsService } from './newsService.js'

// RSS 解析器（使用动态导入避免 ESM 问题）
let Parser: any = null

async function getParser() {
    if (!Parser) {
        const rssParser = await import('rss-parser')
        Parser = rssParser.default
    }
    return new Parser({
        timeout: 30000,
        headers: {
            'User-Agent': 'TongHai CRM RSS Fetcher/1.0',
        },
    })
}

export interface RssFeedInput {
    name: string
    url: string
    category: string
    language?: string
    isActive?: boolean
    fetchInterval?: number
}

export const rssFetchService = {
    /**
     * 获取所有 RSS 源
     */
    async getAllFeeds(includeInactive: boolean = false) {
        const where = includeInactive ? {} : { isActive: true }
        return prisma.rssFeed.findMany({
            where,
            include: {
                _count: {
                    select: { articles: true },
                },
            },
            orderBy: { createdAt: 'desc' },
        })
    },

    /**
     * 获取单个 RSS 源
     */
    async getFeedById(id: string) {
        return prisma.rssFeed.findUnique({
            where: { id },
            include: {
                _count: {
                    select: { articles: true },
                },
            },
        })
    },

    /**
     * 创建 RSS 源
     */
    async createFeed(data: RssFeedInput) {
        return prisma.rssFeed.create({
            data: {
                name: data.name,
                url: data.url,
                category: data.category,
                language: data.language || 'zh',
                isActive: data.isActive ?? true,
                fetchInterval: data.fetchInterval || 60,
            },
        })
    },

    /**
     * 更新 RSS 源
     */
    async updateFeed(id: string, data: Partial<RssFeedInput>) {
        return prisma.rssFeed.update({
            where: { id },
            data,
        })
    },

    /**
     * 删除 RSS 源
     */
    async deleteFeed(id: string) {
        return prisma.rssFeed.delete({
            where: { id },
        })
    },

    /**
     * 抓取单个 RSS 源
     */
    async fetchFeed(feedId: string): Promise<{
        success: boolean
        newCount: number
        error?: string
    }> {
        const feed = await prisma.rssFeed.findUnique({
            where: { id: feedId },
        })

        if (!feed) {
            return { success: false, newCount: 0, error: '订阅源不存在' }
        }

        try {
            const parser = await getParser()
            const result = await parser.parseURL(feed.url)

            let newCount = 0

            for (const item of result.items || []) {
                // 生成 sourceId（用 GUID 或链接）
                const sourceId = item.guid || item.link || item.title

                if (!sourceId) continue

                // 检查是否已存在
                const exists = await newsService.articleExists('rss', sourceId)
                if (exists) continue

                // 创建文章
                try {
                    await newsService.createArticle({
                        title: item.title || '无标题',
                        content: item.content || item.contentSnippet || item.summary || item.description || '',
                        summary: item.contentSnippet || item.summary || item.description?.substring(0, 300),
                        coverImage: extractImageFromContent(item.content || item['content:encoded']),
                        source: 'rss',
                        sourceUrl: item.link,
                        sourceId,
                        author: item.creator || item.author,
                        type: 'INDUSTRY',
                        category: feed.category,
                        status: 'DRAFT', // RSS 抓取的默认为草稿
                        rssFeedId: feed.id,
                        publishedAt: item.pubDate ? new Date(item.pubDate) : undefined,
                    })
                    newCount++
                } catch (err) {
                    console.error(`Failed to create article from RSS item:`, err)
                }
            }

            // 更新抓取时间
            await prisma.rssFeed.update({
                where: { id: feedId },
                data: {
                    lastFetchAt: new Date(),
                    lastError: null,
                },
            })

            return { success: true, newCount }
        } catch (error: any) {
            console.error(`Error fetching RSS feed ${feed.name}:`, error)

            // 记录错误
            await prisma.rssFeed.update({
                where: { id: feedId },
                data: {
                    lastError: error.message || '抓取失败',
                },
            })

            return { success: false, newCount: 0, error: error.message }
        }
    },

    /**
     * 抓取所有活跃的 RSS 源
     */
    async fetchAllFeeds(): Promise<{
        totalFeeds: number
        successCount: number
        newArticles: number
        errors: Array<{ feedId: string; feedName: string; error: string }>
    }> {
        const feeds = await prisma.rssFeed.findMany({
            where: { isActive: true },
        })

        let successCount = 0
        let newArticles = 0
        const errors: Array<{ feedId: string; feedName: string; error: string }> = []

        for (const feed of feeds) {
            const result = await this.fetchFeed(feed.id)
            if (result.success) {
                successCount++
                newArticles += result.newCount
            } else {
                errors.push({
                    feedId: feed.id,
                    feedName: feed.name,
                    error: result.error || '未知错误',
                })
            }
        }

        return {
            totalFeeds: feeds.length,
            successCount,
            newArticles,
            errors,
        }
    },

    /**
     * 测试 RSS 源是否有效
     */
    async testFeed(url: string): Promise<{
        valid: boolean
        title?: string
        itemCount?: number
        error?: string
    }> {
        try {
            const parser = await getParser()
            const result = await parser.parseURL(url)

            return {
                valid: true,
                title: result.title,
                itemCount: result.items?.length || 0,
            }
        } catch (error: any) {
            return {
                valid: false,
                error: error.message || '无法解析 RSS 源',
            }
        }
    },
}

/**
 * 从 HTML 内容中提取第一张图片
 */
function extractImageFromContent(content: string | undefined): string | undefined {
    if (!content) return undefined

    const imgMatch = content.match(/<img[^>]+src=["']([^"']+)["']/i)
    if (imgMatch && imgMatch[1]) {
        return imgMatch[1]
    }

    // 尝试匹配 enclosure 标签中的图片
    const enclosureMatch = content.match(/url=["']([^"']+\.(jpg|jpeg|png|gif|webp))["']/i)
    if (enclosureMatch && enclosureMatch[1]) {
        return enclosureMatch[1]
    }

    return undefined
}

import { prisma } from '../config/index.js'
import { scoringService } from './scoringService.js'
import { workflowService } from './workflowService.js'
import { invoiceService } from './invoiceService.js'

interface ScheduledTask {
    name: string
    cronExpression: string
    handler: () => Promise<any>
    enabled: boolean
    lastRun?: Date
    nextRun?: Date
}

interface TaskResult {
    taskName: string
    success: boolean
    result?: any
    error?: string
    duration: number
}

// 任务注册表
const tasks: Map<string, ScheduledTask> = new Map()
let isRunning = false

export const schedulerService = {
    /**
     * 初始化定时任务
     */
    async initialize(): Promise<void> {
        // 注册默认任务
        this.registerTask({
            name: 'BATCH_SCORE_UPDATE',
            cronExpression: '0 2 * * *', // 每天凌晨2点
            handler: async () => {
                const result = await scoringService.batchUpdateScores()
                return { updated: result.updated, failed: result.failed }
            },
            enabled: true
        })

        this.registerTask({
            name: 'CHECK_OVERDUE_INVOICES',
            cronExpression: '0 9 * * *', // 每天上午9点
            handler: async () => {
                const result = await (invoiceService as any).checkAndMarkOverdue()
                return { marked: result.length }
            },
            enabled: true
        })

        this.registerTask({
            name: 'AUTO_ASSIGN_LEADS',
            cronExpression: '*/30 * * * *', // 每30分钟
            handler: async () => {
                const result = await workflowService.batchAutoAssign()
                return result
            },
            enabled: true
        })

        this.registerTask({
            name: 'CLEANUP_OLD_LOGS',
            cronExpression: '0 3 * * 0', // 每周日凌晨3点
            handler: async () => {
                const thirtyDaysAgo = new Date()
                thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30)

                const result = await prisma.emailLog.deleteMany({
                    where: {
                        createdAt: { lt: thirtyDaysAgo },
                        status: 'SENT'
                    }
                })
                return { deleted: result.count }
            },
            enabled: true
        })

        // 从数据库加载自定义任务配置
        await this.loadTaskConfig()

        console.log(`⏰ 定时任务服务已初始化，共 ${tasks.size} 个任务`)
    },

    /**
     * 注册任务
     */
    registerTask(task: ScheduledTask): void {
        tasks.set(task.name, {
            ...task,
            nextRun: this.calculateNextRun(task.cronExpression)
        })
    },

    /**
     * 从数据库加载任务配置
     */
    async loadTaskConfig(): Promise<void> {
        try {
            const config = await prisma.systemSetting.findUnique({
                where: { key: 'SCHEDULER_CONFIG' }
            })

            if (config?.value) {
                const taskConfig = JSON.parse(config.value) as Record<string, { enabled: boolean; cronExpression?: string }>

                for (const [name, settings] of Object.entries(taskConfig)) {
                    const task = tasks.get(name)
                    if (task) {
                        task.enabled = settings.enabled
                        if (settings.cronExpression) {
                            task.cronExpression = settings.cronExpression
                            task.nextRun = this.calculateNextRun(settings.cronExpression)
                        }
                    }
                }
            }
        } catch (error) {
            console.warn('加载定时任务配置失败:', error)
        }
    },

    /**
     * 保存任务配置到数据库
     */
    async saveTaskConfig(): Promise<void> {
        const config: Record<string, { enabled: boolean; cronExpression: string }> = {}

        for (const [name, task] of tasks) {
            config[name] = {
                enabled: task.enabled,
                cronExpression: task.cronExpression
            }
        }

        await prisma.systemSetting.upsert({
            where: { key: 'SCHEDULER_CONFIG' },
            update: { value: JSON.stringify(config) },
            create: { key: 'SCHEDULER_CONFIG', value: JSON.stringify(config), category: 'SYSTEM' }
        })
    },

    /**
     * 计算下次运行时间（简化版 Cron 解析）
     */
    calculateNextRun(cronExpression: string): Date {
        // 简化实现：返回当前时间 + 间隔
        // 实际生产环境应使用 cron-parser 等库
        const now = new Date()
        const parts = cronExpression.split(' ')

        // 处理常见模式
        if (parts[0].startsWith('*/')) {
            // 每 N 分钟
            const mins = parseInt(parts[0].slice(2))
            now.setMinutes(now.getMinutes() + mins)
        } else if (parts[1].startsWith('*/')) {
            // 每 N 小时
            const hours = parseInt(parts[1].slice(2))
            now.setHours(now.getHours() + hours)
        } else {
            // 默认：下一天的指定时间
            const hour = parseInt(parts[1]) || 0
            const minute = parseInt(parts[0]) || 0
            now.setDate(now.getDate() + 1)
            now.setHours(hour, minute, 0, 0)
        }

        return now
    },

    /**
     * 执行单个任务
     */
    async runTask(taskName: string): Promise<TaskResult> {
        const task = tasks.get(taskName)
        if (!task) {
            return {
                taskName,
                success: false,
                error: '任务不存在',
                duration: 0
            }
        }

        const startTime = Date.now()

        try {
            const result = await task.handler()
            const duration = Date.now() - startTime

            task.lastRun = new Date()
            task.nextRun = this.calculateNextRun(task.cronExpression)

            // 记录执行日志
            await this.logTaskExecution(taskName, true, result, duration)

            return {
                taskName,
                success: true,
                result,
                duration
            }
        } catch (error: any) {
            const duration = Date.now() - startTime

            // 记录执行日志
            await this.logTaskExecution(taskName, false, null, duration, error.message)

            return {
                taskName,
                success: false,
                error: error.message,
                duration
            }
        }
    },

    /**
     * 手动触发任务
     */
    async triggerTask(taskName: string): Promise<TaskResult> {
        console.log(`🔧 手动触发任务: ${taskName}`)
        return this.runTask(taskName)
    },

    /**
     * 检查并执行到期任务
     */
    async checkAndRunDueTasks(): Promise<TaskResult[]> {
        if (isRunning) {
            console.log('⏳ 任务检查已在进行中，跳过')
            return []
        }

        isRunning = true
        const results: TaskResult[] = []
        const now = new Date()

        try {
            for (const [name, task] of tasks) {
                if (!task.enabled) continue
                if (!task.nextRun || task.nextRun > now) continue

                console.log(`⏰ 执行定时任务: ${name}`)
                const result = await this.runTask(name)
                results.push(result)
            }
        } finally {
            isRunning = false
        }

        return results
    },

    /**
     * 记录任务执行日志
     */
    async logTaskExecution(
        taskName: string,
        success: boolean,
        result: any,
        duration: number,
        error?: string
    ): Promise<void> {
        try {
            await prisma.activity.create({
                data: {
                    actionType: 'SCHEDULED_TASK',
                    entityType: 'SYSTEM',
                    entityId: taskName,
                    description: success
                        ? `定时任务 ${taskName} 执行成功，耗时 ${duration}ms`
                        : `定时任务 ${taskName} 执行失败: ${error}`,
                    changes: result ? result : null,
                    actorId: 'system' // 需要一个系统用户 ID
                }
            })
        } catch {
            // 日志记录失败不影响主流程
            console.warn('任务日志记录失败')
        }
    },

    /**
     * 获取所有任务状态
     */
    getTasksStatus(): Array<{
        name: string
        enabled: boolean
        cronExpression: string
        lastRun?: Date
        nextRun?: Date
    }> {
        return Array.from(tasks.values()).map(task => ({
            name: task.name,
            enabled: task.enabled,
            cronExpression: task.cronExpression,
            lastRun: task.lastRun,
            nextRun: task.nextRun
        }))
    },

    /**
     * 更新任务配置
     */
    async updateTask(
        taskName: string,
        updates: { enabled?: boolean; cronExpression?: string }
    ): Promise<boolean> {
        const task = tasks.get(taskName)
        if (!task) return false

        if (updates.enabled !== undefined) {
            task.enabled = updates.enabled
        }

        if (updates.cronExpression) {
            task.cronExpression = updates.cronExpression
            task.nextRun = this.calculateNextRun(updates.cronExpression)
        }

        await this.saveTaskConfig()
        return true
    },

    /**
     * 启动定时任务轮询（开发模式）
     * 生产环境建议使用外部 Cron 服务触发
     */
    startPolling(intervalMs = 60000): NodeJS.Timeout {
        console.log(`⏰ 启动任务轮询，间隔 ${intervalMs / 1000} 秒`)

        return setInterval(async () => {
            const results = await this.checkAndRunDueTasks()
            if (results.length > 0) {
                console.log(`✅ 执行了 ${results.length} 个定时任务`)
            }
        }, intervalMs)
    }
}

