            const input = { name: '高预算', field: 'budgetRange', operator: 'exists', score: 20 }
            const mockCreated = { id: 'rule-new', ...input, isActive: true, sortOrder: 0 }

            prismaMock.scoringRule.create.mockResolvedValue(mockCreated as any)

