// ==================== Language Management ====================
let currentLang = localStorage.getItem('language') || 'zh-TW';

function switchLanguage(lang) {
  currentLang = lang;
  localStorage.setItem('language', lang);

  // Update all elements with data-i18n attribute
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const keys = el.dataset.i18n.split('.');
    let value = i18n[lang];

    for (const key of keys) {
      value = value[key];
    }

    if (value) {
      if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
        el.placeholder = value;
      } else {
        el.textContent = value;
      }
    }
  });

  // Update HTML lang attribute
  document.documentElement.lang = lang === 'zh-TW' ? 'zh-TW' : 'en';

  // Update language toggle buttons
  updateLanguageToggle(lang);
}

function updateLanguageToggle(lang) {
  const toggleBtns = document.querySelectorAll('[data-lang-toggle]');
  toggleBtns.forEach(btn => {
    if (btn.dataset.langToggle === lang) {
      btn.classList.add('active');
    } else {
      btn.classList.remove('active');
    }
  });
}

// Initialize language on page load
document.addEventListener('DOMContentLoaded', () => {
  switchLanguage(currentLang);
  initMobileMenu();
  initSmoothScroll();
  initScrollNavbar();
  initFormValidation();
});

// ==================== Mobile Menu ====================
function initMobileMenu() {
  const menuBtn = document.getElementById('mobile-menu-btn');
  const mobileMenu = document.getElementById('mobile-menu');
  const closeMobileMenu = document.getElementById('close-mobile-menu');

  if (menuBtn && mobileMenu) {
    menuBtn.addEventListener('click', () => {
      mobileMenu.classList.remove('translate-x-full');
    });

    closeMobileMenu?.addEventListener('click', () => {
      mobileMenu.classList.add('translate-x-full');
    });

    // Close menu when clicking a link
    mobileMenu.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        mobileMenu.classList.add('translate-x-full');
      });
    });
  }
}

// ==================== Smooth Scroll ====================
function initSmoothScroll() {
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
      const href = this.getAttribute('href');
      if (href === '#') return;

      const target = document.querySelector(href);
      if (target) {
        e.preventDefault();
        const navHeight = 80;
        const targetPosition = target.offsetTop - navHeight;

        window.scrollTo({
          top: targetPosition,
          behavior: 'smooth'
        });
      }
    });
  });
}

// ==================== Scroll Navbar Effect ====================
function initScrollNavbar() {
  const navbar = document.getElementById('navbar');
  let _lastScroll = 0;

  window.addEventListener('scroll', () => {
    const currentScroll = window.pageYOffset;

    if (currentScroll > 100) {
      navbar?.classList.add('shadow-xl');
    } else {
      navbar?.classList.remove('shadow-xl');
    }

    _lastScroll = currentScroll;
  });
}

// ==================== Form Validation ====================
function initFormValidation() {
  const contactForm = document.getElementById('contact-form');

  if (contactForm) {
    contactForm.addEventListener('submit', async (e) => {
      e.preventDefault();

      // Validate form
      const formData = new FormData(contactForm);
      const data = Object.fromEntries(formData);

      // Check required fields
      if (!data.name || !data.contact) {
        showToast(currentLang === 'zh-TW' ? '請填寫必填欄位' : 'Please fill in required fields', 'error');
        return;
      }

      try {
        // Submit to Formspree or your backend
        const response = await fetch(contactForm.action, {
          method: 'POST',
          body: formData,
          headers: {
            'Accept': 'application/json'
          }
        });

        if (response.ok) {
          showToast(currentLang === 'zh-TW' ? '感謝您的留言，我們會盡快與您聯繫！' : 'Thank you! We will contact you soon.', 'success');
          contactForm.reset();
        } else {
          throw new Error('Form submission failed');
        }
      } catch (error) {
        showToast(currentLang === 'zh-TW' ? '提交失敗，請稍後再試' : 'Submission failed. Please try again.', 'error');
      }
    });
  }
}

// ==================== Toast Notification ====================
