import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { leadApi } from '@/api'
import type { Lead, LeadFilters, PaginationParams } from '@tonghai/shared/types'

export const useLeadStore = defineStore('lead', () => {
    // 状态
    const leads = ref<Lead[]>([])
    const currentLead = ref<Lead | null>(null)
    const loading = ref(false)
    const total = ref(0)
    const page = ref(1)
    const limit = ref(20)
    const filters = ref<LeadFilters>({})
    const stats = ref<{
        total: number
        byStatus: Record<string, number>
        bySource: Record<string, number>
        trend: { date: string; count: number }[]
    } | null>(null)
    const activities = ref<NonNullable<Lead['activities']>>([])

    // 计算属性
    const totalPages = computed(() => Math.ceil(total.value / limit.value))

    // 方法
    async function fetchLeads(customFilters?: LeadFilters, customPagination?: PaginationParams) {
        loading.value = true
        try {
            const result = await leadApi.getList(
                customFilters || filters.value,
                customPagination || { page: page.value, limit: limit.value }
            )
            leads.value = result.data
            total.value = result.pagination.total
            page.value = result.pagination.page
            return result
        } finally {
            loading.value = false
        }
    }

    async function fetchStats() {
        const result = await leadApi.getStats()
        stats.value = result
        return result
    }

    async function fetchRecentActivities(limit = 20) {
        const result = await leadApi.getActivities(limit)
        activities.value = result
        return result
    }

    async function fetchLeadById(id: string) {
        loading.value = true
        try {
            const lead = await leadApi.getById(id)
            currentLead.value = lead
            return lead
        } finally {
            loading.value = false
        }
    }

    async function createLead(payload: Parameters<typeof leadApi.create>[0]) {
        const lead = await leadApi.create(payload)
        leads.value.unshift(lead)
        total.value++
        return lead
    }

    async function updateLead(id: string, payload: Parameters<typeof leadApi.update>[1]) {
        const lead = await leadApi.update(id, payload)
        const index = leads.value.findIndex(l => l.id === id)
        if (index !== -1) {
            leads.value[index] = lead
        }
        if (currentLead.value?.id === id) {
            // 合并已有数据
            currentLead.value = { ...currentLead.value, ...lead }
        }
        return lead
    }

    async function addNote(id: string, content: string) {
        const activity = await leadApi.addNote(id, content)
        if (currentLead.value?.id === id) {
            currentLead.value.activities = currentLead.value.activities || []
            currentLead.value.activities.unshift(activity)
        }
        return activity
    }

    async function assignLead(id: string, assignedToId: string, reason?: string) {
        const lead = await leadApi.assign(id, { assignedToId, reason })
        const index = leads.value.findIndex(l => l.id === id)
        if (index !== -1) {
            leads.value[index] = lead
        }
        return lead
    }

    async function deleteLead(id: string) {
        await leadApi.delete(id)
        leads.value = leads.value.filter(l => l.id !== id)
        total.value--
    }

    async function convertToCustomer(id: string) {
        const result = await leadApi.convertToCustomer(id)
        // 更新本地线索状态
        const index = leads.value.findIndex(l => l.id === id)
        if (index !== -1) {
            leads.value[index] = { ...leads.value[index], status: 'CONVERTED' }
        }
        if (currentLead.value?.id === id) {
            currentLead.value = { ...currentLead.value, status: 'CONVERTED' }
        }
        return result
    }

    function setFilters(newFilters: LeadFilters) {
        filters.value = newFilters
        page.value = 1
    }

    function setPage(newPage: number) {
        page.value = newPage
    }

    return {
        // 状态
        leads,
        currentLead,
        loading,
        total,
        page,
        limit,
        filters,
        stats,
        activities,
        // 计算属性
        totalPages,
        // 方法
        fetchLeads,
        fetchStats,
        fetchRecentActivities,
        fetchLeadById,
        createLead,
        updateLead,
        addNote,
        assignLead,
        deleteLead,
        convertToCustomer,
        setFilters,
        setPage,
    }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { projectApi, type Project } from '@/api/projectApi'

export const useProjectStore = defineStore('project', () => {
    const projects = ref<Project[]>([])
    const currentProject = ref<Project | null>(null)
    const isLoading = ref(false)
    const isSubmitting = ref(false)
    const error = ref<string | null>(null)
    const pagination = ref({
        page: 1,
        limit: 10,
        total: 0,
        totalPages: 1
    })

    // 按状态分组（用于看板）
    const projectsByStatus = computed(() => {
        const grouped: Record<string, Project[]> = {
            PLANNING: [],
            ACTIVE: [],
            ON_HOLD: [],
            COMPLETED: [],
            ARCHIVED: []
        }

        projects.value.forEach(p => {
            if (grouped[p.status]) {
                grouped[p.status].push(p)
            }
        })

        return grouped
    })

    // 获取列表
    async function fetchProjects(params: any = {}) {
        isLoading.value = true
        try {
            const response = await projectApi.getList(params)
            projects.value = response.data
            pagination.value = response.pagination
        } catch (err: any) {
            error.value = err.message || '获取项目列表失败'
            console.error(err)
        } finally {
            isLoading.value = false
        }
    }

    // 获取详情
    async function fetchProjectById(id: string) {
        isLoading.value = true
        currentProject.value = null
        try {
            const data = await projectApi.getById(id)
            currentProject.value = data
            return data
        } catch (err: any) {
            error.value = err.message || '获取项目详情失败'
            throw err
        } finally {
            isLoading.value = false
        }
    }

    // 创建
    async function createProject(data: Partial<Project>) {
        isSubmitting.value = true
        try {
            const newProject = await projectApi.create(data)
            projects.value.unshift(newProject)
            return newProject
        } finally {
            isSubmitting.value = false
        }
    }

    // 更新
    async function updateProject(id: string, data: Partial<Project>) {
        isSubmitting.value = true
        try {
            const updated = await projectApi.update(id, data)
            // 更新列表中的数据
            const index = projects.value.findIndex(p => p.id === id)
            if (index !== -1) {
                projects.value[index] = { ...projects.value[index], ...updated }
            }
            // 如果当前是详情页
            if (currentProject.value?.id === id) {
                currentProject.value = { ...currentProject.value, ...updated }
            }
            return updated
        } finally {
            isSubmitting.value = false
        }
    }

    // 更新状态（拖拽）
    async function updateProjectStatus(id: string, status: string) {
        // 乐观更新
        const project = projects.value.find(p => p.id === id)
        const oldStatus = project?.status

        if (project) {
            project.status = status as any
        }

        try {
            await projectApi.updateStatus(id, status)
        } catch (err) {
            // 回滚
            if (project && oldStatus) {
                project.status = oldStatus
            }
            throw err
        }
    }

    return {
        projects,
        currentProject,
        isLoading,
        isSubmitting,
        error,
        pagination,
        projectsByStatus,
        fetchProjects,
        fetchProjectById,
        createProject,
        updateProject,
        updateProjectStatus
    }
})

import { defineStore } from 'pinia'
import { ref } from 'vue'
import { taskApi } from '@/api'
import type { Task, TaskStatus } from '@tonghai/shared/types'

export const useTaskStore = defineStore('task', () => {
    // 状态
    const tasks = ref<Task[]>([])
    const boardData = ref<Record<TaskStatus, Task[]> | null>(null)
    const loading = ref(false)
    const stats = ref<{
        total: number
        overdue: number
        byStatus: Record<string, number>
    } | null>(null)

    // 方法
    async function fetchBoard(assignedToId?: string) {
        loading.value = true
        try {
            const result = await taskApi.getBoard(assignedToId)
            boardData.value = result
            return result
        } finally {
            loading.value = false
        }
    }

    async function fetchTasks(filters: Record<string, unknown> = {}) {
        loading.value = true
        try {
            const result = await taskApi.getList(filters)
            tasks.value = result.data
            return result
        } finally {
            loading.value = false
        }
    }

    async function fetchStats(assignedToId?: string) {
        const result = await taskApi.getStats(assignedToId)
        stats.value = result
        return result
    }

    async function createTask(payload: Parameters<typeof taskApi.create>[0]) {
        const task = await taskApi.create(payload)
        // 更新看板数据
        if (boardData.value) {
            boardData.value[task.status].unshift(task)
        }
        return task
    }

    async function updateTask(id: string, payload: Parameters<typeof taskApi.update>[1]) {
        const task = await taskApi.update(id, payload)

        // 更新看板数据
        if (boardData.value) {
            // 从旧状态列表中移除
            for (const status of Object.keys(boardData.value) as TaskStatus[]) {
                const index = boardData.value[status].findIndex(t => t.id === id)
                if (index !== -1) {
                    boardData.value[status].splice(index, 1)
                    break
                }
            }
            // 添加到新状态列表
            boardData.value[task.status].unshift(task)
        }

        return task
    }

    async function moveTask(id: string, status: TaskStatus) {
        // 仅调用 API 更新状态
        // 注意：这里不需要手动更新 boardData 的数组顺序，
        // 因为 vuedraggable 已经通过双向绑定处理了 UI 上的移动。
        // 我们只需要确保后端状态同步，并更新本地 task 对象的 status 字段即可。

        await taskApi.update(id, { status })

        // 更新本地 task 对象引用中的状态，以防万一
        if (boardData.value && boardData.value[status]) {
            const task = boardData.value[status].find(t => t.id === id)
            if (task) {
                task.status = status
            }
        }
    }

    async function deleteTask(id: string) {
        await taskApi.delete(id)

        // 更新看板数据
        if (boardData.value) {
            for (const status of Object.keys(boardData.value) as TaskStatus[]) {
                const index = boardData.value[status].findIndex(t => t.id === id)
                if (index !== -1) {
                    boardData.value[status].splice(index, 1)
                    break
                }
            }
        }
    }

    return {
        // 状态
        tasks,
        boardData,
        loading,
        stats,
        // 方法
        // 方法
        fetchBoard,
        fetchTasks,
        fetchStats,
        createTask,
        updateTask,
        moveTask,
        deleteTask,
    }
})

/// <reference types="vite/client" />

declare module '*.vue' {
    import type { DefineComponent } from 'vue'
    const component: DefineComponent<{}, {}, any>
    export default component
}

declare module 'element-plus/dist/locale/zh-cn.mjs'

import axios from 'axios'
import type { AxiosError, InternalAxiosRequestConfig, AxiosRequestConfig } from 'axios'

const axiosInstance = axios.create({
    baseURL: import.meta.env.VITE_API_BASE_URL || '/api/v1', // Fallback if env not set
    timeout: 10000,
    headers: {
        'Content-Type': 'application/json',
    },
})

// 请求拦截器
axiosInstance.interceptors.request.use(
    (config: InternalAxiosRequestConfig) => {
        // Website 可能不需要 Token，但预留扩展
        return config
    },
    (error) => Promise.reject(error)
)

// 响应拦截器 - 智能解包 (Smart Unwrap)
axiosInstance.interceptors.response.use(
    (response) => {
        const res = response.data
        // 检查是否为标准响应结构 { code, data, ... }
        if (res && typeof res === 'object' && 'code' in res) {
            if (res.code === 200) {
                return res.data
            }
            // 非 200 抛出错误
            return Promise.reject(new Error(res.message || 'Error'))
        }

        // 旧格式 (或者类似 News 目前的 { success: true, data: ... } 但没有 code 字段?)
        // News 后端目前返回 { success: true, data: ... } (无 code)
        // 所以目前会走这里，返回 res。
        return res
    },
    (error: AxiosError) => {
        return Promise.reject(error)
    }
)

/**
 * 封装后的 API 客户端
 * 由于响应拦截器已解包，返回类型为 Promise<any> 而非 AxiosResponse
 */
const apiClient = {
    get: <T = any>(url: string, config?: AxiosRequestConfig): Promise<T> => {
        return axiosInstance.get(url, config) as unknown as Promise<T>
    },
    post: <T = any>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> => {
        return axiosInstance.post(url, data, config) as unknown as Promise<T>
    },
    put: <T = any>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> => {
        return axiosInstance.put(url, data, config) as unknown as Promise<T>
    },
    delete: <T = any>(url: string, config?: AxiosRequestConfig): Promise<T> => {
        return axiosInstance.delete(url, config) as unknown as Promise<T>
    },
    patch: <T = any>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> => {
        return axiosInstance.patch(url, data, config) as unknown as Promise<T>
    },
}

export default apiClient

/// <reference types="vite/client" />

declare module '*.vue' {
    import type { DefineComponent } from 'vue'
    const component: DefineComponent<{}, {}, any>
    export default component
}
